/* Vragenbank PA-toets, Wft Schadeverzekering Particulier. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["schade-particulier"] = [
["Op welk moment geldt de wettelijke mededelingsplicht van de verzekeringnemer volgens BW 7 titel 17?", [["Vóór het sluiten van de verzekeringsovereenkomst.", "De wettelijke mededelingsplicht ziet op de precontractuele fase; wijzigingen tijdens de looptijd moeten alleen worden gemeld als de polis dat bepaalt."], ["Gedurende de hele looptijd van de verzekering.", "De wet regelt geen doorlopende mededelingsplicht; een meldplicht voor risicowijziging volgt alleen uit de polisvoorwaarden."], ["Uitsluitend op het moment van een schademelding.", "Bij schade geldt een meldings- en informatieplicht, maar dat is een andere verplichting dan de precontractuele mededelingsplicht."], ["Alleen bij elke stilzwijgende verlenging van de polis.", "Een verlenging is geen nieuwe totstandkoming waarbij de wettelijke mededelingsplicht opnieuw ontstaat."]]],
["Welke feiten moet een verzekeringnemer op grond van de mededelingsplicht melden?", [["Feiten die hij kent of behoort te kennen en die relevant zijn voor de beslissing van de verzekeraar.", "Dat is de wettelijke maatstaf: het gaat om kennis van de verzekeringnemer en de relevantie voor de acceptatie- en premiebeslissing."], ["Alleen feiten die de verzekeringnemer zelf van belang vindt voor de hoogte van de premie.", "De maatstaf is niet het subjectieve oordeel van de klant, maar wat hij behoort te begrijpen over de beslissing van de verzekeraar."], ["Alle feiten over zijn persoon, gezin en financiën, ook als die voor het risico of de premie geen rol spelen.", "De plicht is beperkt tot feiten die van belang kunnen zijn voor de beslissing van de verzekeraar."], ["Alleen feiten die blijken uit openbare registers, zoals het Kadaster of het handelsregister.", "Openbaarheid is niet bepalend; ook niet-geregistreerde feiten, zoals eerdere schades, kunnen gemeld moeten worden."]]],
["Een verzekeraar gebruikt bij het aanvragen een vragenlijst. Na een schade blijkt een relevant feit waar niet naar gevraagd is. Wat geldt?", [["Zij kan zich er niet op beroepen, tenzij de klant opzet had de verzekeraar te misleiden.", "Bij een vragenlijst mag de klant afgaan op de gestelde vragen; alleen bij opzet om de verzekeraar te misleiden ligt dat anders."], ["Zij mag de uitkering naar evenredigheid verminderen, omdat het feit relevant was.", "Proportionele vermindering is een sanctie bij schending van de mededelingsplicht, maar over niet-gevraagde feiten kan de verzekeraar in beginsel geen beroep doen."], ["Zij mag de polis met terugwerkende kracht vernietigen wegens dwaling over het risico.", "Voor niet-gevraagde feiten is er zonder opzet tot misleiding geen grond voor zo'n beroep."], ["Zij hoeft niet uit te keren, omdat de klant ook ongevraagd alles moest melden.", "Juist bij een vragenlijst beperkt de wet de mededelingsplicht feitelijk tot de gestelde vragen."]]],
["Mevrouw Bakker meldt bij het afsluiten van een inboedelverzekering een eerdere inbraak niet. De verzekeraar had haar bij juiste melding geaccepteerd tegen een hogere premie. Na een nieuwe inbraak ontdekt de verzekeraar dit. Wat is in beginsel het gevolg (geen opzet tot misleiding)?", [["Uitkering naar verhouding van de betaalde premie tot de premie bij juiste melding.", "De wet kiest voor een proportionele uitkering: de klant krijgt wat bij de juiste premie in verhouding zou zijn verzekerd."], ["Geen uitkering, omdat elke schending van de mededelingsplicht tot verval leidt.", "Volledige weigering geldt pas als de verzekeraar bij kennis van de ware stand van zaken geen verzekering zou hebben gesloten, of bij opzet tot misleiding."], ["Volledige uitkering, waarbij de verzekeraar alleen de premie alsnog verhoogt.", "De wet laat de verzekeraar de uitkering verminderen; volledige vergoeding met naheffing van premie is niet de wettelijke regel."], ["Uitkering van de helft van de schade, omdat schuld bij beide partijen ligt.", "Er bestaat geen vaste 50%-regel; de vermindering volgt uit de verhouding tussen de premies."]]],
["Binnen welke termijn moet een verzekeraar na ontdekking van schending van de mededelingsplicht de verzekeringnemer daarop wijzen om zich op de gevolgen te kunnen beroepen?", [["Binnen twee maanden na de ontdekking.", "De verzekeraar moet binnen twee maanden na ontdekking op de niet-nakoming wijzen en de gevolgen noemen; anders vervalt zijn beroep daarop."], ["Binnen veertien dagen na de ontdekking.", "Veertien dagen is de aanmaningstermijn bij premiebetaling, niet de termijn bij de mededelingsplicht."], ["Binnen drie jaar na de ontdekking.", "Drie jaar is de verjaringstermijn voor vorderingen tegen de verzekeraar; voor dit beroep geldt een veel kortere termijn."], ["Er geldt geen termijn; de verzekeraar kan zich er altijd op beroepen.", "De wet stelt juist een termijn om de verzekeringnemer duidelijkheid te geven."]]],
["Wat mag een verzekeraar doen als de verzekeringnemer de mededelingsplicht heeft geschonden met het opzet de verzekeraar te misleiden?", [["Uitkering weigeren en de verzekering opzeggen met onmiddellijke ingang.", "Bij opzet tot misleiding vervalt het recht op uitkering en mag de verzekeraar de overeenkomst direct beëindigen."], ["Alleen de premie met terugwerkende kracht verhogen.", "Bij opzet tot misleiding gaat de wet verder dan premieherstel; de klant verliest zijn recht op uitkering."], ["Alleen naar evenredigheid uitkeren.", "Proportionele uitkering is de hoofdregel zonder opzet; bij opzet tot misleiding hoeft de verzekeraar niets uit te keren."], ["De verzekering pas opzeggen tegen de eerstvolgende contractvervaldatum, met behoud van uitkering.", "De wet staat bij opzet tot misleiding opzegging met onmiddellijke ingang toe en het recht op uitkering vervalt."]]],
["De verzekeringnemer betaalt een vervolgpremie niet op tijd. Wanneer mag de verzekeraar de dekking opschorten?", [["Na een vergeefse aanmaning om binnen veertien dagen te betalen.", "Voor vervolgpremies treedt verzuim pas in na een aanmaning met een betalingstermijn van veertien dagen; daarna mag de dekking worden opgeschort."], ["Direct op de dag na de vervaldag, zonder aanmaning vooraf.", "Voor vervolgpremies is eerst een aanmaning nodig; opschorting zonder aanmaning is niet toegestaan."], ["Pas nadat de premieachterstand drie maanden heeft geduurd.", "De wet kent geen termijn van drie maanden; beslissend is de vergeefse aanmaning met een termijn van veertien dagen."], ["Pas nadat de rechter de opschorting van dekking heeft toegestaan.", "Tussenkomst van de rechter is niet nodig; de opschorting volgt uit de polis na intreden van verzuim."]]],
["Wat moet een verzekerde volgens de wet doen zodra hij weet of behoort te weten dat er een schade is waarvoor dekking kan bestaan?", [["De schade zo spoedig redelijkerwijs mogelijk melden en de nodige informatie geven.", "Dit is de wettelijke meldings- en informatieplicht na een schadevoorval."], ["Eerst zelf de schade laten herstellen en daarna de herstelnota met foto's insturen.", "Eigenmachtig herstel kan de schadevaststelling bemoeilijken; de wet vraagt eerst tijdige melding en informatie."], ["De schade pas melden als vaststaat welke partij aansprakelijk is.", "De meldplicht hangt niet af van de aansprakelijkheidsvraag; melden moet zo spoedig mogelijk."], ["De schade binnen een jaar melden, omdat anders elk recht vervalt.", "De wet noemt geen vaste meldtermijn van een jaar; maatstaf is 'zo spoedig redelijkerwijs mogelijk'."]]],
["Een verzekerde meldt een waterschade te laat, maar zonder opzet tot misleiding. Wat mag de verzekeraar in beginsel doen?", [["De uitkering verminderen met het nadeel dat hij door de late melding lijdt.", "Bij schending van de meldplicht mag de verzekeraar de schade verhalen die hij daardoor lijdt; verval van het hele recht kan alleen als hij in een redelijk belang is geschaad en dit is bedongen."], ["De hele uitkering weigeren, ook als hij geen enkel nadeel heeft geleden.", "Volledig verval is alleen mogelijk als de verzekeraar in een redelijk belang is geschaad en dat in de polis staat, of bij opzet tot misleiding."], ["De verzekering met terugwerkende kracht ontbinden wegens wanprestatie.", "Late melding geeft geen grond om de overeenkomst met terugwerkende kracht te ontbinden."], ["Niets, omdat de wet geen gevolgen verbindt aan een late schademelding.", "De wet geeft de verzekeraar wel een sanctie, namelijk vermindering met het nadeel dat hij lijdt."]]],
["Welke vergoeding geldt volgens BW 7 voor redelijke kosten die de verzekerde maakt om dreigende schade te voorkomen of te beperken (bereddingskosten)?", [["Ze worden vergoed, ook als daardoor de verzekerde som wordt overschreden.", "Bereddingskosten komen voor rekening van de verzekeraar, ook boven de verzekerde som, omdat beredding ook de verzekeraar dient."], ["Ze worden alleen vergoed als de maatregel de schade daadwerkelijk heeft beperkt.", "Ook redelijke maatregelen zonder resultaat worden vergoed; succes is geen voorwaarde."], ["Ze worden niet vergoed, omdat ze onder het eigen risico van de verzekerde vallen.", "De wet verplicht de verzekeraar juist om redelijke bereddingskosten te vergoeden."], ["Ze worden vergoed tot maximaal de helft van de verzekerde som van de polis.", "De wet kent geen maximum van de halve verzekerde som; vergoeding kan zelfs boven de som uitkomen."]]],
["Wat zegt de wet over schade die een verzekerde met opzet of door roekeloosheid veroorzaakt bij een schadeverzekering?", [["De verzekeraar keert aan die verzekerde geen schadevergoeding uit.", "De wet sluit uitkering uit aan de verzekerde die de schade met opzet of door roekeloosheid veroorzaakte."], ["De verzekeraar keert de helft uit.", "De wet kent bij opzet of roekeloosheid geen gedeeltelijke uitkering aan die verzekerde."], ["De verzekeraar keert volledig uit, maar mag de polis daarna opzeggen.", "Uitkering is bij opzet of roekeloosheid van die verzekerde juist uitgesloten."], ["Alleen opzet is wettelijk uitgesloten; roekeloosheid valt altijd onder de dekking.", "De wettelijke regeling noemt naast opzet ook roekeloosheid."]]],
["Wat is volgens BW 7 de hoofdregel voor schade door een eigen gebrek van de verzekerde zaak?", [["Die schade wordt niet vergoed, tenzij anders is overeengekomen.", "Eigen gebrek is een wettelijke uitsluiting van regelend recht; de polis mag dekking geven."], ["Die schade wordt altijd vergoed, omdat de zaak verzekerd is.", "De wet sluit schade door eigen gebrek juist uit, tenzij de polis anders bepaalt."], ["Die schade wordt alleen vergoed bij een allriskdekking, op grond van de wet.", "Het is de polis, niet de wet, die eigen gebrek eventueel meeverzekert."], ["Die schade valt onder de bereddingskosten.", "Bereddingskosten zijn kosten om schade te beperken; eigen gebrek is een oorzaak van schade."]]],
["Een woning met een waarde van € 250.000 is verzekerd voor € 200.000. Er ontstaat een schade van € 50.000. Er is geen garantie tegen onderverzekering of eerste-risicodekking. Hoeveel keert de verzekeraar uit?", [["€ 40.000.", "Bij onderverzekering wordt evenredig vergoed: € 50.000 × 200.000 / 250.000 = € 40.000."], ["€ 50.000.", "Volledige vergoeding zou gelden bij een eerste-risicodekking of garantie tegen onderverzekering, die hier ontbreken."], ["€ 37.500.", "Dit bedrag volgt niet uit de evenredigheidsregel; de verhouding verzekerde som / waarde is 0,8."], ["€ 30.000.", "Hier is ten onrechte het verschil van € 50.000 tussen waarde en som van de schade afgetrokken; dat is niet de evenredigheidsregel."]]],
["Iemand heeft hetzelfde risico bij twee verzekeraars gedekt (samenloop). Wat is het uitgangspunt in BW 7?", [["Hij krijgt zijn schade één keer vergoed; de verzekeraars verdelen die onderling.", "Samenloop doorbreekt het indemniteitsbeginsel niet: de verzekerde krijgt zijn schade één keer vergoed en de verzekeraars hebben onderling regres."], ["Hij ontvangt van beide verzekeraars de volledige schade, omdat hij twee premies betaalt.", "Dubbele vergoeding is in strijd met het indemniteitsbeginsel."], ["Alleen de verzekeraar met de oudste polis keert uit; de jongere polis vervalt.", "Ouderdom van de polis is niet de wettelijke maatstaf voor samenloop."], ["Beide verzekeringen zijn nietig, omdat dubbele dekking wettelijk verboden is.", "Samenloop maakt verzekeringen niet nietig; de wet regelt juist hoe zij samen uitkeren."]]],
["Wat houdt subrogatie in bij een schadeverzekering?", [["Na uitkering gaat de verhaalsvordering op de aansprakelijke derde over op de verzekeraar.", "Door subrogatie kan de verzekeraar de uitgekeerde schade verhalen op de veroorzaker."], ["De verzekerde mag zowel de verzekeraar als de aansprakelijke derde volledig laten betalen.", "Dan zou de verzekerde dubbel ontvangen; subrogatie voorkomt dat juist."], ["De verzekeraar mag na een uitkering de premie van de verzekerde eenzijdig verhogen.", "Premieaanpassing heeft niets te maken met subrogatie."], ["Een nieuwe verzekeraar neemt bij een overstap de lopende polis met alle rechten over.", "Overstappen is een nieuwe overeenkomst; subrogatie gaat over overgang van verhaalsrechten."]]],
["Wat is de verjaringstermijn van een rechtsvordering tot uitkering tegen een verzekeraar?", [["Drie jaar na de dag na bekendwording met de opeisbaarheid van de uitkering.", "Dat is de wettelijke termijn; stuiting is mogelijk door een schriftelijke mededeling."], ["Vijf jaar na de dag waarop het schadevoorval heeft plaatsgevonden of is ontdekt.", "Vijf jaar is de relatieve verjaringstermijn bij onrechtmatige daad, niet de termijn voor vorderingen op een verzekeraar."], ["Twintig jaar na de dag waarop de verzekeringsovereenkomst is gesloten.", "Twintig jaar is een absolute termijn uit het aansprakelijkheidsrecht, niet de termijn voor vorderingen op een verzekeraar."], ["Eén jaar na de dag waarop de schade bij de verzekeraar is gemeld.", "De wet kent geen termijn van één jaar voor deze vordering."]]],
["De verzekeraar wijst een claim ondubbelzinnig schriftelijk af en wijst op de gevolgen. Wat gebeurt er met de verjaring?", [["Er begint een nieuwe verjaringstermijn van zes maanden.", "Na een ondubbelzinnige erkenning of afwijzing loopt een nieuwe termijn van zes maanden."], ["De verjaringstermijn van drie jaar begint opnieuw te lopen.", "Na een duidelijke afwijzing is de nieuwe termijn juist korter: zes maanden."], ["De vordering is vanaf de dag van afwijzing direct verjaard.", "Een afwijzing laat de vordering niet direct verjaren; de klant heeft nog zes maanden om actie te nemen."], ["De verjaring is voorgoed gestuit en kan niet meer intreden.", "Stuiting leidt tot een nieuwe termijn, niet tot een vordering die nooit meer verjaart."]]],
["Een consument heeft een inboedelverzekering die na het eerste contractjaar stilzwijgend is verlengd. Wat geldt voor opzegging door de consument?", [["Hij kan op elk moment opzeggen met ten hoogste één maand opzegtermijn.", "Na stilzwijgende verlenging mag een consument dagelijks opzeggen met maximaal een maand opzegtermijn."], ["Hij kan alleen opzeggen tegen de eerstvolgende jaarlijkse contractvervaldatum.", "Dat geldt niet meer na stilzwijgende verlenging; de consument mag op elk moment opzeggen."], ["Hij kan opzeggen, maar moet een opzegtermijn van drie maanden aanhouden.", "Een opzegtermijn van meer dan een maand mag na stilzwijgende verlenging niet worden bedongen."], ["Hij kan alleen opzeggen nadat de verzekeraar de premie heeft verhoogd.", "De wet beperkt het opzegrecht niet tot een premieverhoging."]]],
["Wat is het wezenlijke verschil tussen een schadeverzekering en een sommenverzekering?", [["Een schadeverzekering vergoedt vermogensschade; een sommenverzekering keert een vast bedrag uit.", "Dit is het wettelijke onderscheid; het indemniteitsbeginsel geldt alleen voor schadeverzekeringen."], ["Een schadeverzekering is altijd wettelijk verplicht; een sommenverzekering is altijd een vrijwillige keuze.", "Verplichting staat los van het type: de meeste schadeverzekeringen zijn vrijwillig."], ["Een sommenverzekering kent altijd een eigen risico; een schadeverzekering nooit.", "Een eigen risico komt vooral voor bij schadeverzekeringen; het is geen onderscheidend kenmerk."], ["Een schadeverzekering keert alleen uit bij overlijden; een sommenverzekering bij schade.", "Uitkering bij overlijden is typisch voor een sommenverzekering, zoals een levensverzekering."]]],
["Een verzamelaar laat zijn schilderij vóór het afsluiten van de verzekering door een deskundige taxeren en de verzekeraar aanvaardt de taxatie. Wat is daarvan het gevolg bij schade?", [["De getaxeerde waarde geldt in beginsel, tenzij de verzekeraar bedrog aantoont.", "Een vooraf door een deskundige vastgestelde taxatie voorkomt discussie over de waarde; de verzekeraar kan die in beginsel alleen bij bedrog aantasten."], ["De verzekeraar mag de waarde na een schade altijd opnieuw laten vaststellen.", "Juist daarom wordt vooraf getaxeerd: de verzekeraar is in beginsel aan de taxatie gebonden."], ["De verzekeraar keert bij totaalverlies het dubbele van de getaxeerde waarde uit.", "Taxatie legt de waarde vast; het indemniteitsbeginsel staat geen dubbele uitkering toe."], ["De taxatie heeft alleen betekenis voor de hoogte van de premie, niet voor de schade.", "De taxatie heeft vooral betekenis voor de schadeuitkering."]]],
["Een consument sluit online een reisverzekering voor een reis van twee weken. Kan hij de overeenkomst binnen veertien dagen kosteloos ontbinden op grond van de regels voor financiële diensten op afstand?", [["Nee, kortlopende reis- en bagageverzekeringen (korter dan een maand) zijn uitgezonderd.", "Kortlopende reis- en bagageverzekeringen zijn uitgezonderd van de bedenktijd bij financiële diensten op afstand."], ["Ja, voor elke verzekering die op afstand is gesloten geldt veertien dagen bedenktijd.", "Er gelden uitzonderingen, waaronder kortlopende reis- en bagageverzekeringen."], ["Ja, maar alleen zolang de reis nog niet is begonnen en er geen schade is gemeld.", "De wet maakt die uitzondering niet; voor deze verzekeringen is er geen ontbindingsrecht."], ["Nee, een ontbindingsrecht op afstand bestaat bij geen enkele schadeverzekering.", "Voor veel schadeverzekeringen op afstand geldt wel een bedenktijd van veertien dagen."]]],
["Wat is het 'verzekerd belang' bij een schadeverzekering?", [["Het financiële belang van de verzekerde bij het uitblijven van schade.", "Zonder belang lijdt de verzekerde geen schade en heeft een schadeverzekering geen zin."], ["Het bedrag van de jaarlijkse premie die de verzekeringnemer betaalt.", "De premie is de prijs van de dekking, niet het belang."], ["De winst die de verzekeraar naar verwachting op de polis maakt.", "Het verzekerd belang is dat van de verzekerde, niet dat van de verzekeraar."], ["Het deel van de schade dat de verzekerde per gebeurtenis zelf als eigen risico draagt.", "Het eigen risico is het deel van de schade voor eigen rekening, niet het verzekerd belang."]]],
["Wat houdt het indemniteitsbeginsel in?", [["De verzekerde mag er door de uitkering financieel niet op vooruitgaan.", "Een schadeverzekering vergoedt de schade, niet meer; zo wordt verrijking en een prikkel tot schade voorkomen."], ["De verzekeraar moet bij elke schade de volledige verzekerde som uitkeren.", "De verzekerde som is een maximum; uitgekeerd wordt de werkelijke schade."], ["De verzekerde heeft op grond van de wet altijd recht op nieuwwaarde.", "Nieuwwaarde is een toegestane, maar contractuele afwijking; het beginsel zelf gaat over het voorkomen van verrijking."], ["De verzekerde mag dezelfde schade bij meerdere verzekeraars claimen.", "Dubbele vergoeding is juist in strijd met het indemniteitsbeginsel."]]],
["Waarom wordt vergoeding op basis van nieuwwaarde bij inboedel aanvaard, ondanks het indemniteitsbeginsel?", [["Omdat anders de verzekerde moet bijbetalen voor vervanging; polisgrenzen beperken verrijking.", "Nieuwwaarde is een geaccepteerde afwijking; met grenzen, zoals dagwaarde voor sterk verouderde zaken, blijft verrijking beperkt."], ["Omdat het indemniteitsbeginsel volgens de wet niet geldt voor inboedelverzekeringen.", "Het beginsel geldt voor alle schadeverzekeringen; nieuwwaarde is een contractuele afwijking."], ["Omdat de wet nieuwwaardevergoeding voorschrijft voor alle particuliere schadeverzekeringen.", "De wet schrijft nieuwwaarde niet voor; het is een polisafspraak."], ["Omdat nieuwwaarde in de praktijk altijd lager uitvalt dan de dagwaarde van een zaak.", "Het is andersom: nieuwwaarde is gelijk aan of hoger dan dagwaarde."]]],
["Wat is het verschil tussen een aftrekfranchise en een integrale franchise?", [["Aftrek: eigen risico gaat altijd van de schade af; integraal: boven de grens alles vergoed.", "Bij een integrale franchise is de grens een drempel: schade eronder wordt niet vergoed, schade erboven volledig."], ["Integraal: de verzekerde betaalt altijd de hele schade; aftrek: alleen kleine schades.", "Boven de drempel vergoedt de verzekeraar bij een integrale franchise juist alles."], ["Aftrek: geldt alleen bij aansprakelijkheid; integraal: geldt alleen bij brand- en stormverzekeringen.", "Aftrekfranchises komen bij vrijwel alle schadeverzekeringen voor."], ["Er is geen verschil; beide termen beschrijven hetzelfde vaste eigen risico per schade.", "De werking verschilt duidelijk bij schades boven de grens."]]],
["Meneer De Vries heeft een volledige cascoverzekering met een eigen risico van € 250. Zijn schade bedraagt € 3.000 en is gedekt. Wat keert de verzekeraar uit (aftrekfranchise)?", [["€ 2.750.", "Bij een aftrekfranchise wordt het eigen risico van de gedekte schade afgetrokken: € 3.000 − € 250."], ["€ 3.000.", "Het eigen risico wordt hier niet vergoed; dat komt voor rekening van de verzekerde."], ["€ 3.250.", "Het eigen risico wordt afgetrokken, niet opgeteld."], ["€ 2.500.", "Hier is het eigen risico twee keer afgetrokken."]]],
["Waarom kiezen klanten soms voor een hoger vrijwillig eigen risico?", [["Om een lagere premie te betalen en kleine schades zelf te dragen.", "Een hoger eigen risico verlaagt de premie; passend als de klant kleine schades zelf kan opvangen."], ["Om bij een grote schade een hogere uitkering boven de verzekerde som te ontvangen.", "Een hoger eigen risico verlaagt juist de uitkering per schade en verhoogt de verzekerde som niet."], ["Omdat de wet dit verplicht stelt voor beginnende bestuurders.", "Een verhoogd eigen risico voor jonge bestuurders volgt uit polisvoorwaarden, niet uit de wet, en is dan niet vrijwillig."], ["Om de evenredigheidsregel bij onderverzekering te voorkomen.", "Onderverzekering hangt af van de verhouding verzekerde som en waarde, niet van het eigen risico."]]],
["Wat kenmerkt een allriskdekking bij inboedel of woonhuis ten opzichte van een dekking op basis van genoemde gevaren?", [["Plotselinge, onvoorziene schade is gedekt, behalve wat is uitgesloten.", "Bij allrisk geldt in beginsel dekking tenzij een uitsluiting van toepassing is; bij genoemde gevaren moet de oorzaak in de opsomming staan."], ["Alle denkbare schade is gedekt, zonder enige uitsluiting in de polis.", "Ook allrisk kent uitsluitingen, zoals slijtage, eigen gebrek of opzet."], ["Alleen schade door brand, storm en inbraak is gedekt, en verder niets.", "Dat is een beperkte dekking op basis van genoemde gevaren."], ["Schade is gedekt zonder eigen risico, omdat allrisk de duurste vorm is.", "Allriskdekkingen hebben juist vaak een eigen risico, zeker voor de 'overige' schades."]]],
["Wat houdt een verzekering 'op eerste risico' in?", [["Vergoeding tot de verzekerde som, zonder evenredigheid bij onderverzekering.", "Bij eerste risico wordt geen onderverzekering toegepast; de som is het maximum."], ["Vergoeding van alleen de eerste schade per verzekeringsjaar, daarna niet meer.", "Eerste risico gaat niet over het aantal schades, maar over het ontbreken van evenredigheid."], ["De verzekerde draagt zelf het eerste deel van elke schade als eigen risico.", "Dat is een eigen risico, geen eerste-risicodekking."], ["De dekking gaat pas in na een wachttijd vanaf de ingangsdatum van de polis.", "Een wachttijd heeft niets te maken met eerste risico."]]],
["Welke schade valt doorgaans ook bij een allriskdekking niet onder de verzekering?", [["Geleidelijke slijtage en veroudering van een zaak.", "Slijtage is niet plotseling en onvoorzien en daarmee standaard uitgesloten."], ["Een televisie die plotseling van de kast valt en daarbij kapotgaat.", "Dit is een plotselinge en onvoorziene gebeurtenis, het typische voorbeeld van een allriskschade."], ["Inkt die per ongeluk op een bank wordt gemorst.", "Een onverwacht ongeluk in huis is bij allrisk in de regel gedekt, eventueel met een eigen risico."], ["Een brandschade aan de keuken.", "Brand is ook bij beperktere dekkingen gedekt, dus zeker bij allrisk."]]],
["Op wie rust de verzekeringsplicht op grond van de Wet aansprakelijkheidsverzekering motorrijtuigen (WAM)?", [["Op de kentekenhouder van het motorrijtuig.", "De WAM legt de plicht bij de houder; de RDW controleert of voor elk kenteken een WA-verzekering bestaat."], ["Op iedere bestuurder afzonderlijk.", "De verzekering dekt wel de aansprakelijkheid van iedere bestuurder, maar de plicht om te verzekeren ligt bij de houder."], ["Op de fabrikant of dealer van het voertuig.", "Fabrikant en dealer hebben geen WAM-verplichting voor auto's van klanten."], ["Op de eigenaar van de grond waarop de auto geparkeerd staat.", "De verzekeringsplicht hangt aan het voertuig en de houder, niet aan de parkeerplaats."]]],
["Welk bijzonder recht geeft de WAM aan een benadeelde?", [["Een eigen recht om de WA-verzekeraar van de veroorzaker rechtstreeks aan te spreken.", "Dankzij deze directe actie hoeft de benadeelde niet via de veroorzaker te procederen."], ["Het recht om de premie van de veroorzaker te laten verhogen.", "De benadeelde heeft geen zeggenschap over de premie van een ander."], ["Het recht op vergoeding van alle schade door de eigen cascoverzekeraar, ongeacht schuld.", "De WAM regelt de positie van de benadeelde tegenover de WA-verzekeraar, niet tegenover de eigen casco."], ["Het recht om het rijbewijs van de veroorzaker te laten innemen.", "Rijbewijsmaatregelen zijn strafrechtelijk of bestuursrechtelijk, niet geregeld in de WAM."]]],
["Een bestuurder veroorzaakt onder invloed van alcohol een aanrijding. De polis sluit rijden onder invloed uit. Wat geldt voor de benadeelde tegenpartij?", [["De WA-verzekeraar vergoedt de benadeelde en verhaalt dit daarna op de verzekerde.", "Polisuitsluitingen kunnen niet aan de benadeelde worden tegengeworpen; de verzekeraar heeft wel regres op de verzekerde."], ["De benadeelde krijgt niets, omdat de polis rijden onder invloed uitdrukkelijk uitsluit.", "Juist om benadeelden te beschermen, mag de WA-verzekeraar zulke verweren niet tegen hen inroepen."], ["Het Waarborgfonds Motorverkeer betaalt altijd in plaats van de verzekeraar.", "Het Waarborgfonds springt vooral bij als er geen verzekering is of de veroorzaker onbekend is; hier is een verzekeraar."], ["De benadeelde moet de bestuurder eerst strafrechtelijk laten veroordelen.", "Voor vergoeding via de WA-verzekeraar is geen strafrechtelijke veroordeling nodig."]]],
["Wanneer kan een benadeelde in het verkeer een beroep doen op het Waarborgfonds Motorverkeer?", [["Als de schade is veroorzaakt door een onbekend of onverzekerd motorrijtuig.", "Het Waarborgfonds vangt schade op die anders onvergoed blijft, bijvoorbeeld bij doorrijden na een ongeval."], ["Altijd, als de eigen cascoverzekering de schade aan de auto niet dekt.", "Het fonds is geen vangnet voor een ontbrekende eigen cascodekking."], ["Als de benadeelde de aanrijding zelf heeft veroorzaakt en geen casco heeft.", "Wie zelf de schade veroorzaakt, heeft geen aanspraak op het fonds voor eigen schade."], ["Alleen bij schade die in het buitenland door een Nederlander is veroorzaakt.", "Het fonds is bedoeld voor schade in Nederland door onbekende of onverzekerde motorrijtuigen."]]],
["Een automobilist rijdt een fietsend kind van 10 jaar aan. Wat geldt op grond van art. 185 Wegenverkeerswet voor de letselschade van het kind?", [["Volledige vergoeding, tenzij het kind opzettelijk of bewust roekeloos handelde.", "Voor kinderen onder de 14 jaar geldt de 100%-regel; alleen opzet of bewuste roekeloosheid doorbreekt die."], ["Vergoeding van 50%, omdat het kind zelf ook een verkeersfout heeft gemaakt.", "De 50%-regel geldt voor letsel van volwassen fietsers en voetgangers, niet voor kinderen onder de 14 jaar."], ["Geen vergoeding als het kind door rood licht reed, wegens eigen schuld.", "Een verkeersfout van een kind onder de 14 jaar is geen opzet of bewuste roekeloosheid."], ["Vergoeding naar rato van schuld, zoals bij botsingen tussen twee auto's.", "Bij kinderen onder de 14 jaar wordt niet naar rato van schuld verdeeld; de 100%-regel gaat voor."]]],
["Een volwassen fietser raakt gewond bij een aanrijding met een auto. Hij heeft zelf een verkeersfout gemaakt, maar er is geen overmacht voor de automobilist. Wat geldt voor zijn letselschade?", [["Hij krijgt ten minste 50% vergoed; bij minder eigen schuld meer.", "De 50%-regel waarborgt dat een volwassen niet-gemotoriseerde verkeersdeelnemer minimaal de helft van zijn letselschade vergoed krijgt."], ["Hij krijgt niets, omdat hij zelf een fout maakte.", "Een eigen fout leidt niet tot nul, tenzij er opzet of bewuste roekeloosheid is."], ["Hij krijgt altijd 100% vergoed.", "De 100%-regel geldt voor kinderen onder de 14 jaar."], ["Hij krijgt een vast bedrag dat jaarlijks door de overheid wordt bepaald.", "De vergoeding hangt af van de werkelijke schade en de eigen schuld, niet van een vast bedrag."]]],
["Een automobilist rijdt door eigen schuld tegen een boom en raakt gewond. Hij heeft alleen een WA-verzekering. Welke verzekering zou zijn eigen letselschade wél dekken?", [["Een schadeverzekering voor inzittenden (SVI).", "De SVI vergoedt letsel- en zaakschade van inzittenden, inclusief de bestuurder, ook als hij zelf schuld heeft."], ["De WA-verzekering, als hij het eigen risico betaalt.", "De WA-verzekering dekt alleen schade aan anderen, nooit de eigen letselschade van de bestuurder."], ["Het Waarborgfonds Motorverkeer.", "Het Waarborgfonds keert niet uit aan een bestuurder die het ongeval zelf veroorzaakt."], ["De aansprakelijkheidsverzekering voor particulieren (AVP).", "De AVP sluit schade met motorrijtuigen uit en dekt geen eigen letsel."]]],
["Wat is het verschil tussen een schadeverzekering voor inzittenden (SVI) en een ongevallenverzekering voor inzittenden (OVI)?", [["De SVI vergoedt de werkelijke schade; de OVI keert vaste bedragen uit.", "De SVI is een schadeverzekering, de OVI een sommenverzekering; daardoor biedt de SVI meestal een ruimere vergoeding."], ["De SVI geldt alleen voor de bestuurder; de OVI alleen voor de passagiers.", "Beide verzekeringen gelden in beginsel voor alle inzittenden, inclusief de bestuurder."], ["De OVI vergoedt ook schade aan de auto; de SVI dekt alleen letselschade.", "Geen van beide is een cascoverzekering; de SVI vergoedt wel schade aan spullen van inzittenden."], ["Er is geen verschil; het zijn twee namen voor hetzelfde verzekeringsproduct.", "Het verschil tussen werkelijke schade en vaste bedragen is wezenlijk."]]],
["Welke schade is bij een beperkt-cascoverzekering doorgaans NIET gedekt?", [["Schade aan de eigen auto door een aanrijding door eigen schuld.", "Eigen-schuldschade is het onderscheidende verschil tussen beperkt en volledig casco."], ["Diefstal van de auto vanaf een openbare parkeerplaats.", "Diefstal is een kerngevaar van beperkt casco."], ["Ruitschade door een opspattend steentje op de snelweg.", "Ruitschade valt doorgaans onder beperkt casco."], ["Schade door een boom die tijdens een storm op de geparkeerde auto valt.", "Storm en ander natuurgeweld vallen doorgaans onder beperkt casco."]]],
["Meneer Jansen rijdt bij het inparkeren met zijn auto tegen een paaltje. Er is geen tegenpartij. Onder welke dekking valt de schade aan zijn auto?", [["Een volledige cascoverzekering.", "Alleen volledig casco dekt schade aan de eigen auto door eigen toedoen."], ["De WA-verzekering van de auto.", "WA dekt schade die de bestuurder aan anderen toebrengt, niet aan zijn eigen auto."], ["De beperkt-cascoverzekering.", "Beperkt casco dekt van buiten komende gevaren zoals brand, diefstal en storm, niet eigen-schuldschade."], ["De schadeverzekering inzittenden.", "De SVI dekt schade van inzittenden, niet schade aan het voertuig zelf."]]],
["Een verzekerde meldt een schade bij zijn autoverzekeraar. De schade wordt volledig verhaald op de aansprakelijke tegenpartij. Wat betekent dit doorgaans voor zijn bonus-malustrede?", [["Hij valt niet terug, omdat de schade volledig is verhaald.", "Bonus-malusregelingen laten volledig verhaalde schades meestal buiten beschouwing."], ["Hij valt evenveel treden terug als bij een eigen-schuldschade.", "Een volledig verhaalde schade kost de verzekeraar per saldo niets en leidt in de regel niet tot terugval."], ["Hij verliest in één keer al zijn opgebouwde schadevrije jaren.", "Volledig verlies van schadevrije jaren hoort niet bij een volledig verhaalde schade."], ["Hij valt één trede terug, omdat elke gemelde schade meetelt.", "Een volledig verhaalde schade kost de verzekeraar per saldo niets en telt in de regel niet mee."]]],
["Een klant heeft een kleine eigen-schuldschade van enkele honderden euro's aan een andere auto gereden. Welk advies kan passend zijn om terugval op de bonus-malusladder te voorkomen?", [["Nagaan of hij de schade bij de verzekeraar kan terugkopen door het bedrag terug te betalen.", "Veel verzekeraars bieden de mogelijkheid een schade terug te kopen; bij kleine schades kan dat goedkoper zijn dan de premiestijging."], ["De schade niet melden en de tegenpartij vragen te wachten tot na de premievervaldatum.", "De schade aan een ander moet worden gemeld; niet melden schaadt de benadeelde en kan het recht op dekking aantasten."], ["De polis direct opzeggen en de auto elders verzekeren zonder de schade te vermelden.", "Dat is misleiding; schadevrije jaren worden centraal geregistreerd en gecontroleerd."], ["De schade bij de verzekeraar opgeven als cascoschade in plaats van als WA-schade.", "Een schade onjuist voorstellen is fraude en geen passend advies."]]],
["Hoe weet een nieuwe autoverzekeraar hoeveel schadevrije jaren een overstappende klant heeft opgebouwd?", [["Via de centrale registratie van schadevrije jaren (Roy-data).", "Verzekeraars registreren schadevrije jaren centraal, zodat de nieuwe verzekeraar die kan controleren."], ["Uitsluitend via de verklaring van de klant op het aanvraagformulier.", "De opgave van de klant wordt gecontroleerd aan de hand van de centrale registratie."], ["Via een opgave van de RDW op basis van de kentekenregistratie.", "De RDW registreert kentekens en verzekeringsplicht, maar niet de opgebouwde schadevrije jaren."], ["Via de Belastingdienst, die de schadehistorie van auto's bijhoudt.", "De Belastingdienst houdt geen schadehistorie van autoverzekeringen bij."]]],
["Een klant schaft een speed pedelec aan (elektrische fiets met trapondersteuning tot ongeveer 45 km/u). Wat geldt voor de verzekering?", [["Het is een bromfiets met kenteken en valt onder de WAM-verzekeringsplicht.", "Speed pedelecs gelden als bromfiets; voor bromfietsen geldt de WAM-plicht."], ["Schade aan derden valt onder de AVP, net als bij een gewone fiets of e-bike.", "De AVP sluit motorrijtuigen zoals bromfietsen uit; voor de speed pedelec is een WA-verzekering nodig."], ["Verzekeren is niet nodig, omdat de berijder zelf moet blijven trappen.", "Bij een gewone e-bike tot 25 km/u is dat zo, maar een speed pedelec is wettelijk een bromfiets."], ["Alleen een cascoverzekering is wettelijk verplicht voor dit voertuig.", "De wettelijke plicht betreft aansprakelijkheid (WA), niet casco."]]],
["Wat is de herbouwwaarde van een woning?", [["De kosten om de woning na schade op dezelfde plek en met dezelfde bestemming te herbouwen.", "De herbouwwaarde is de basis voor de verzekerde som van een opstalverzekering."], ["De marktwaarde die de eigenaar bij verkoop van de woning inclusief grond zou ontvangen.", "Marktwaarde bevat onder meer de grondwaarde en de ligging; die worden niet herbouwd."], ["De WOZ-waarde die de gemeente jaarlijks voor de onroerendezaakbelasting vaststelt.", "De WOZ-waarde is een fiscale waarde inclusief grond en zegt weinig over de herbouwkosten."], ["De executiewaarde die een taxateur voor de hypotheekverstrekker vaststelt.", "De executiewaarde is een waarde bij gedwongen verkoop voor de geldverstrekker, niet de kosten van herbouw."]]],
["Wat houdt een garantie tegen onderverzekering bij een woonhuisverzekering in?", [["Geen onderverzekering, mits de waarde volgens de voorgeschreven methode is bepaald en wijzigingen zijn gemeld.", "De garantie geeft zekerheid over volledige vergoeding, maar is gebonden aan voorwaarden zoals een herbouwwaardemeter of taxatie en het melden van verbouwingen."], ["Bij schade wordt altijd de volledige verzekerde som uitgekeerd, ongeacht de werkelijke omvang van de schade.", "De garantie voorkomt onderverzekering, maar laat het indemniteitsbeginsel intact."], ["De klant hoeft verbouwingen en uitbreidingen van de woning nooit meer aan de verzekeraar door te geven.", "Ingrijpende verbouwingen of uitbreidingen moeten juist worden gemeld om de garantie te behouden."], ["De verzekeraar garandeert dat de premie gedurende de looptijd niet stijgt, ook niet bij indexering.", "De garantie gaat over de vergoeding bij schade, niet over premiestabiliteit."]]],
["Na een brand besluit de eigenaar zijn woning niet te herbouwen. Wat bepalen woonhuispolissen hier gebruikelijk voor de schadevergoeding?", [["Vergoeding op basis van de verkoopwaarde zonder grond, als die lager is dan de herbouwwaarde.", "Wie niet herbouwt, heeft geen herbouwkosten; vergoeding op verkoopwaarde voorkomt verrijking."], ["Vergoeding van de volledige herbouwwaarde, omdat de premie altijd op die waarde is gebaseerd.", "Bij niet-herbouwen zou volledige herbouwwaarde kunnen leiden tot verrijking; polissen beperken dat."], ["Geen vergoeding, omdat de verzekerde niet aan zijn herbouwplicht voldoet.", "Ook zonder herbouw is er schade; die wordt vergoed, alleen op een andere basis."], ["Vergoeding van de WOZ-waarde inclusief grond, omdat de woning verloren is.", "Grond gaat bij brand niet verloren en wordt niet vergoed."]]],
["Wat is het verschil tussen nieuwwaarde en dagwaarde bij inboedel?", [["Nieuwwaarde: prijs van nieuwe gelijkwaardige zaken; dagwaarde: nieuwwaarde minus slijtage en veroudering.", "Dit zijn vaste begrippen; polissen bepalen wanneer op dagwaarde wordt vergoed, bijvoorbeeld bij sterk verouderde zaken."], ["Dagwaarde: de oorspronkelijke aankoopprijs; nieuwwaarde: de huidige verkoopprijs op een tweedehandsmarkt.", "Dagwaarde houdt rekening met slijtage en veroudering; nieuwwaarde is de prijs van nieuwe vergelijkbare zaken."], ["Nieuwwaarde geldt alleen voor kunst en antiek; dagwaarde geldt voor alle overige inboedel.", "Voor kunst en antiek wordt juist vaak de vervangingswaarde of taxatiewaarde gebruikt."], ["Er is geen verschil bij zaken jonger dan tien jaar; daarna geldt automatisch en altijd de dagwaarde.", "Ook jonge zaken slijten; het verschil hangt niet af van een vaste leeftijdsgrens."]]],
["Welke gebeurtenis valt doorgaans onder het begrip 'brand' in een woonhuis- of inboedelpolis?", [["Een vuur met vlammen buiten een haard dat zich zelfstandig kan uitbreiden.", "Dit is de gangbare definitie; zonder vlammen en zelfstandige uitbreiding is het geen brand."], ["Een broeiende stapel natte kleding die veel rook ontwikkelt, maar geen vlammen.", "Broeien zonder vlammen voldoet niet aan de branddefinitie."], ["Een tafelblad dat schroeit doordat er een hete pan op is gezet.", "Schroeien en zengen zijn in polissen uitdrukkelijk geen brand."], ["Een kunststof bak die naast de kachel door de hitte is gesmolten.", "Smelten zonder vlammen geldt niet als brand."]]],
["Vanaf welke windsnelheid spreken de meeste woonhuis- en inboedelpolissen van 'storm'?", [["Ten minste 14 meter per seconde (windkracht 7).", "Dit is de gangbare definitie in Nederlandse polissen; de verzekerde kan gegevens van het KNMI gebruiken."], ["Bij elke windstoot die zichtbare schade veroorzaakt.", "Polissen noemen juist een minimum windsnelheid."], ["Pas vanaf windkracht 12, oftewel orkaankracht.", "Dat zou de dekking sterk beperken; de gangbare grens ligt bij windkracht 7."], ["Alleen als het KNMI code rood heeft afgegeven.", "Een weeralarm is geen dekkingsvoorwaarde; bepalend is de windsnelheid."]]],
["Na een diefstal uit een woning stelt de verzekeraar dat er geen dekking is. Welke voorwaarde stellen veel inboedelpolissen bij diefstal?", [["Dat er sporen van braak zijn bij het binnendringen van de woning.", "Veel polissen eisen sporen van braak; zonder sporen is diefstal moeilijk te onderscheiden van verlies of fraude."], ["Dat de dader binnen een maand door de politie is aangehouden.", "Opsporing van de dader is geen dekkingsvoorwaarde."], ["Dat de verzekerde zelf thuis was op het moment van de diefstal.", "Diefstal tijdens afwezigheid is juist de klassieke gedekte situatie."], ["Dat de gestolen zaken jonger zijn dan vijf jaar op de schadedatum.", "De leeftijd van de zaken bepaalt de waardering, niet of er dekking is."]]],
["Welke waterschade is in een standaard woonhuispolis doorgaans gedekt?", [["Water dat plotseling uit een leiding of aangesloten toestel stroomt door een defect.", "Leidingwater is het klassieke gedekte watergevaar."], ["Water dat de kelder binnenkomt door langzaam stijgend grondwater na een natte periode.", "Grondwater is doorgaans uitgesloten; het is geen plotselinge gebeurtenis."], ["Vocht dat ontstaat door langdurig achterstallig onderhoud aan het dak van de woning.", "Slecht onderhoud is een standaard uitsluiting."], ["Optrekkend vocht in de muren dat in de loop van jaren schimmel heeft veroorzaakt.", "Optrekkend vocht is een geleidelijk proces en niet gedekt."]]],
["Een huurder heeft op eigen kosten een nieuwe keuken in de huurwoning laten plaatsen. Hoe is dit gewoonlijk verzekerd?", [["Als huurdersbelang op de inboedelverzekering van de huurder.", "Veranderingen en verbeteringen die een huurder op eigen kosten aanbrengt, vallen meestal onder huurdersbelang in de inboedelpolis."], ["Automatisch op de opstalverzekering van de verhuurder van de woning.", "De verhuurder heeft geen belang bij een door de huurder betaalde keuken en verzekert die niet."], ["Op de aansprakelijkheidsverzekering van de huurder.", "De AVP dekt schade aan anderen, niet eigen investeringen."], ["Dit kan niet worden verzekerd.", "Het huurdersbelang is juist een gangbare dekking."]]],
["Een klant koopt een appartement in een gebouw met een Vereniging van Eigenaars (VvE). Wat is gebruikelijk voor de opstalverzekering?", [["De VvE verzekert het gebouw; de eigenaar verzekert zijn inboedel en eigen verbeteringen.", "De opstal van een appartementencomplex wordt doorgaans door de VvE verzekerd; de eigenaar regelt de rest zelf."], ["Iedere eigenaar sluit een eigen opstalverzekering af voor het volledige gebouw.", "Dat zou tot dubbele dekking leiden; de VvE verzekert het gebouw."], ["Een appartement hoeft niet te worden verzekerd, omdat de VvE een reservefonds heeft.", "Het gebouw moet wel worden verzekerd, alleen gebeurt dat via de VvE."], ["De gemeente verzekert het gebouw, omdat het om gestapelde bouw gaat.", "De gemeente heeft geen rol bij de verzekering van particuliere gebouwen."]]],
["Waarvoor dient een inboedelwaardemeter?", [["Om de inboedelwaarde in te schatten op basis van kenmerken van het huishouden.", "Bij gebruik van de waardemeter bieden verzekeraars vaak een garantie tegen onderverzekering."], ["Om de marktwaarde van de woning voor de hypotheekaanvraag vast te stellen.", "Voor de woningwaarde bij een hypotheek is een taxatierapport nodig, geen inboedelwaardemeter."], ["Om na een schade de dagwaarde van elk afzonderlijk voorwerp te bepalen.", "De waardemeter schat de totale inboedel vooraf; de schade wordt per schade vastgesteld."], ["Om de premie van de opstalverzekering op basis van de herbouwwaarde te bepalen.", "De opstalpremie is gebaseerd op de herbouwwaarde, niet op een inboedelwaardemeter."]]],
["De familie Smit gaat voor een jaar naar het buitenland en laat de woning leeg staan. Wat is het passende advies?", [["De verzekeraar vooraf informeren, omdat leegstand de dekking kan beperken.", "Leegstand vergroot onder meer het risico op inbraak en onopgemerkte schade; veel polissen eisen melding en beperken de dekking."], ["Niets doen, omdat een woonhuispolis altijd geldt, ongeacht bewoning of leegstand.", "Veel polissen beperken de dekking bij leegstand of als die niet is gemeld."], ["De verzekeringen opzeggen, omdat een lege woning geen risico loopt.", "Het gebouw loopt nog steeds risico op brand en storm; opzeggen is onverstandig."], ["Alleen de AVP aanpassen, omdat die het buitenlandverblijf moet dekken.", "Leegstand raakt vooral de woonhuis- en inboedelverzekering, niet de AVP."]]],
["Waarom kennen inboedelpolissen vaak een apart maximum voor lijfsieraden en andere kostbaarheden?", [["Omdat zij klein, waardevol en diefstalgevoelig zijn.", "Een maximum beperkt het risico voor de verzekeraar; wie meer heeft, kan een aparte kostbaarhedendekking afsluiten."], ["Omdat de wet sieraden van inboedeldekking uitsluit.", "De maxima volgen uit de polis, niet uit de wet."], ["Omdat sieraden juridisch niet tot de inboedel horen.", "Sieraden horen tot de inboedel; alleen de vergoeding is beperkt."], ["Omdat de premie anders onder de assurantiebelasting valt.", "Assurantiebelasting staat los van de maxima voor sieraden in de polis."]]],
["Welke aansprakelijkheid dekt een aansprakelijkheidsverzekering voor particulieren (AVP)?", [["Aansprakelijkheid als particulier, niet in de uitoefening van beroep of bedrijf.", "De AVP is bedoeld voor het privéleven; beroeps- en bedrijfsaansprakelijkheid vraagt een andere verzekering."], ["Alle aansprakelijkheid, dus ook bij werkzaamheden als zelfstandig ondernemer.", "Aansprakelijkheid als ondernemer valt buiten de AVP."], ["Schade die de verzekerde per ongeluk aan zijn eigen spullen toebrengt.", "Een AVP dekt schade aan anderen, niet eigen schade."], ["Schade aan derden veroorzaakt met de eigen auto of motor van de verzekerde.", "Schade met motorrijtuigen is uitgesloten; daarvoor dient de WA-verzekering."]]],
["Wat zijn de vereisten voor aansprakelijkheid uit onrechtmatige daad?", [["Onrechtmatigheid, toerekenbaarheid, schade, causaal verband en relativiteit.", "Alle vereisten moeten zijn vervuld voordat iemand op grond van onrechtmatige daad aansprakelijk is."], ["Schade en een geldige aansprakelijkheidsverzekering bij de veroorzaker.", "Een verzekering is geen vereiste voor aansprakelijkheid; de wettelijke vereisten zijn veel uitgebreider."], ["Opzet van de dader en een onherroepelijke strafrechtelijke veroordeling.", "Ook nalatigheid kan onrechtmatig zijn; een strafrechtelijke veroordeling is niet nodig."], ["Een schriftelijke overeenkomst tussen partijen en een ingebrekestelling.", "Aansprakelijkheid uit onrechtmatige daad bestaat juist zonder overeenkomst; een ingebrekestelling hoort bij wanprestatie."]]],
["Een kind van 9 jaar gooit met een steen de ruit van de buren in. Wie is aansprakelijk?", [["De ouders, op grond van risicoaansprakelijkheid voor kinderen onder de 14 jaar.", "Ouders zijn aansprakelijk voor kinderen jonger dan 14 jaar als de gedraging een onrechtmatige daad zou zijn bij een ouder persoon."], ["Het kind zelf, omdat het de ruit heeft ingegooid.", "Een kind onder de 14 jaar is niet zelf aansprakelijk; de wet legt de aansprakelijkheid bij de ouders."], ["Niemand; kinderen onder de 14 jaar en hun ouders zijn wettelijk niet aansprakelijk te maken.", "Het kind zelf niet, maar de ouders wel; zij zijn risicoaansprakelijk."], ["Alleen de school, als het na schooltijd gebeurde.", "De school heeft na schooltijd geen toezicht; de wet wijst de ouders aan."]]],
["Een jongen van 15 jaar veroorzaakt schade bij een ander. Wat geldt voor de aansprakelijkheid van zijn ouders?", [["Zij zijn aansprakelijk, tenzij hun niet te verwijten valt dat zij het niet beletten.", "Voor kinderen van 14 en 15 jaar geldt een schuldaansprakelijkheid van de ouders met een omgekeerde bewijslast."], ["Zij zijn altijd aansprakelijk, zonder dat tegenbewijs mogelijk is.", "De zuivere risicoaansprakelijkheid geldt alleen voor kinderen onder de 14 jaar."], ["Zij zijn nooit aansprakelijk; alleen de jongen zelf kan worden aangesproken.", "De jongen kan zelf aansprakelijk zijn, maar de ouders kunnen dat daarnaast ook zijn."], ["Zij zijn alleen aansprakelijk als de jongen nog bij hen inwoont en geen inkomen heeft.", "Inwoning of inkomen is niet het wettelijke criterium; de regel hangt af van leeftijd en verwijtbaarheid."]]],
["De hond van mevrouw Visser bijt een voorbijganger. Wat geldt voor haar aansprakelijkheid?", [["Als bezitter van de hond is zij risicoaansprakelijk, ook zonder schuld.", "De bezitter van een dier is aansprakelijk voor schade door het eigen gedrag van het dier; schuld is niet nodig."], ["Zij is alleen aansprakelijk als zij de hond slecht heeft opgevoed of niet aanlijnde.", "Schuld is niet vereist; het gaat om risicoaansprakelijkheid, ongeacht opvoeding of aanlijnen."], ["De gemeente is aansprakelijk als de hond aangelijnd was.", "De gemeente is geen bezitter van het dier."], ["Zij is niet aansprakelijk als de hond een stamboom heeft.", "Een stamboom speelt geen rol bij de aansprakelijkheid."]]],
["Sanne leent de laptop van een vriendin en laat die per ongeluk vallen. Wat is het belangrijkste aandachtspunt bij de AVP?", [["Schade aan zaken onder opzicht is in veel AVP-polissen uitgesloten of beperkt gedekt.", "Bij geleende of gehuurde zaken speelt de opzichtsbepaling; de dekking verschilt per polis."], ["Schade aan geleende zaken is bij elke AVP-polis zonder beperking volledig gedekt.", "Veel polissen beperken of sluiten opzichtschade uit."], ["De schade valt onder de inboedelverzekering van Sanne, omdat zij de laptop gebruikte.", "De laptop is niet van Sanne en hoort niet tot haar inboedel."], ["De schade valt onder de inboedelverzekering van de vriendin, die moet daar eerst claimen.", "De vriendin hoeft niet eerst haar eigen polis aan te spreken; de vraag is of Sanne via haar AVP dekking heeft voor opzichtschade."]]],
["Een groep jongeren vernielt opzettelijk een bushokje. Tim hoorde bij de groep maar deed zelf niet mee en had geen opzet. Hij wordt op grond van groepsaansprakelijkheid aangesproken. Wat bepalen veel AVP-polissen hierover?", [["Tim kan dekking hebben; de verzekerden met opzet hebben geen dekking.", "Veel polissen beperken de opzetuitsluiting tot de verzekerde die zelf opzet had."], ["Alle groepsleden hebben volledige dekking, ook wie zelf opzet had.", "Wie zelf opzet had, is uitgesloten van dekking."], ["Niemand van de groep heeft dekking, omdat er opzettelijk is vernield.", "Veel polissen geven juist dekking voor een verzekerde zonder eigen opzet."], ["Tim heeft alleen dekking als de politie tegen hem geen proces-verbaal opmaakt.", "Een proces-verbaal is geen criterium voor dekking."]]],
["Wat is de relatieve verjaringstermijn voor een vordering tot schadevergoeding uit onrechtmatige daad?", [["Vijf jaar na bekendheid met de schade en de aansprakelijke persoon.", "Daarnaast geldt een absolute termijn; de termijn van vijf jaar loopt vanaf bekendheid."], ["Drie jaar na de dag waarop de schade is ontstaan, ongeacht bekendheid.", "Drie jaar is de termijn voor vorderingen tegen een verzekeraar; bij onrechtmatige daad telt bovendien de bekendheid."], ["Eén jaar na de dag waarop de benadeelde de schade heeft ontdekt.", "Een termijn van één jaar geldt niet voor onrechtmatige daad."], ["Tien jaar na de dag waarop de schadeveroorzakende gebeurtenis plaatsvond.", "Een termijn van tien jaar geldt niet als relatieve termijn; de relatieve termijn is vijf jaar vanaf bekendheid."]]],
["Wat is de vrije advocaatkeuze bij een rechtsbijstandverzekering?", [["Het recht om in een procedure zelf een advocaat of andere bevoegde rechtshulpverlener te kiezen.", "Dit recht volgt uit Europees recht; de verzekeraar mag de kosten wel binnen redelijke grenzen beperken."], ["Het recht om voor elk juridisch probleem direct een eigen advocaat op kosten van de verzekeraar te nemen.", "De vrije keuze geldt voor procedures en bij belangenconflicten; daarbuiten mag de verzekeraar eigen juristen inzetten."], ["Het recht van de verzekeraar om in een procedure de advocaat van de tegenpartij aan te wijzen.", "De verzekeraar heeft geen zeggenschap over de advocaat van de tegenpartij."], ["Het recht om de kosten van de gekozen advocaat altijd onbeperkt vergoed te krijgen.", "Vrije keuze betekent niet onbeperkte vergoeding; een redelijk kostenmaximum is toegestaan."]]],
["Een klant sluit een rechtsbijstandverzekering en schakelt een maand later hulp in bij een conflict met zijn aannemer dat al maanden speelt. Wat is het waarschijnlijke antwoord van de verzekeraar?", [["Geen dekking, omdat het geschil al bestond of voorzienbaar was.", "Rechtsbijstandverzekeringen dekken geen conflicten die al bestonden of te verwachten waren toen de polis werd afgesloten."], ["Volledige dekking, omdat de premie vanaf de ingangsdatum is betaald.", "Premiebetaling verandert niets aan de voorwaarde dat het geschil na aanvang onzeker moet zijn."], ["Gedeeltelijke dekking, namelijk voor de helft van de juridische kosten.", "Er bestaat geen gedeeltelijke dekking voor bestaande geschillen."], ["Dekking, mits de klant een hoger eigen risico voor deze zaak betaalt.", "Een eigen risico maakt een bestaand geschil niet alsnog verzekerd."]]],
["Wat is het doel van een wachttijd in een rechtsbijstandverzekering?", [["Voorkomen dat iemand zich verzekert als een conflict al dreigt.", "Gedurende de wachttijd ontstane geschillen zijn niet gedekt; zo blijft de verzekering betaalbaar voor iedereen."], ["De verzekeraar tijd geven om een geschikte advocaat te zoeken.", "De wachttijd gaat over de ingangsdatum van de dekking, niet over de behandeling."], ["De premie pas te innen nadat de wachttijd is verstreken.", "Premie is vanaf de ingangsdatum verschuldigd, ook tijdens de wachttijd."], ["De klant de kans geven de polis kosteloos te ontbinden.", "Kosteloos ontbinden hoort bij een bedenktijd, niet bij een wachttijd."]]],
["Verzekerde en rechtsbijstandverzekeraar verschillen van mening over de haalbaarheid van een procedure. Wat biedt de geschillenregeling in de meeste polissen?", [["Een oordeel van een externe advocaat naar keuze, op kosten van de verzekeraar.", "De geschillenregeling waarborgt een onafhankelijk oordeel over de aanpak van de zaak."], ["Een verplichte gang naar Kifid voordat de zaak inhoudelijk verder kan worden behandeld.", "Kifid gaat over klachten, niet over de inhoudelijke aanpak; de geschillenregeling zit in de polis."], ["Een definitieve beslissing door de verzekeraar zelf, zonder verdere toetsing.", "De geschillenregeling bestaat juist om dat te voorkomen."], ["Een procedure bij de rechter, waarvan de verzekerde de kosten zelf voorschiet.", "De geschillenregeling is een interne regeling met een extern advocaatoordeel, geen gerechtelijke procedure op eigen kosten."]]],
["Welke annuleringsreden is bij een annuleringsverzekering doorgaans gedekt?", [["Ernstige ziekte of overlijden van een naast familielid vóór vertrek.", "Annuleringsverzekeringen dekken alleen onvoorziene, in de polis genoemde gebeurtenissen; ernstige ziekte en overlijden zijn kernredenen."], ["Geen zin meer in de reis door een verandering van plannen.", "Een eigen keuze is geen onvoorziene gebeurtenis en dus niet gedekt."], ["Een goedkopere aanbieding voor dezelfde reis bij een ander bureau.", "Prijsverschil is geen verzekerde annuleringsreden."], ["Slechte weersvoorspellingen voor de periode van de reis.", "Slecht weer is geen gedekte annuleringsreden."]]],
["Hoe verhoudt de dekking voor geneeskundige kosten in een reisverzekering zich tot de basisverzekering (Zvw)?", [["Zij vult aan: zij dekt buitenlandse kosten die de zorgverzekering niet vergoedt.", "Een zorgverzekering vergoedt in het buitenland vaak niet alles; de reisverzekering vult het verschil aan, afhankelijk van de voorwaarden."], ["Zij vervangt de zorgverzekering volledig zolang de verzekerde op reis is.", "De zorgverzekering blijft gelden; de reisverzekering vult aan."], ["Zij vergoedt alleen zorgkosten die na terugkeer in Nederland worden gemaakt.", "Een reisverzekering is juist bedoeld voor kosten tijdens een reis, ook in het buitenland."], ["Zij is wettelijk verplicht voor iedereen die buiten Europa op reis gaat.", "Een reisverzekering is vrijwillig, ook voor reizen buiten Europa."]]],
["Op welke basis vergoedt een reisverzekering doorgaans gestolen bagage?", [["Op dagwaarde, met maxima per categorie en een eigen risico.", "Reisverzekeringen werken meestal met dagwaarde en limieten, bijvoorbeeld voor elektronica en sieraden."], ["Altijd op nieuwwaarde, zonder maximum.", "Een onbeperkte nieuwwaardevergoeding is ongebruikelijk bij bagage."], ["Op basis van de aankoopprijs, ook als die decennia geleden was.", "De aankoopprijs houdt geen rekening met slijtage en veroudering."], ["Op basis van een vast bedrag per koffer.", "Vergoeding hangt af van de werkelijke waarde, niet van het aantal koffers."]]],
["Een vakantiegebied wordt kort voor vertrek getroffen door een natuurramp. Welke regeling kan bij een pakketreis van een aangesloten reisorganisatie uitkomst bieden?", [["Het Calamiteitenfonds Reizen, dat calamiteiten op de bestemming dekt.", "Het Calamiteitenfonds dekt calamiteiten op de bestemming bij aangesloten reisorganisaties, iets wat annuleringsverzekeringen vaak uitsluiten."], ["Stichting Garantiefonds Reisgelden, dat ook natuurrampen vergoedt.", "SGR beschermt bij insolventie van de reisorganisatie, niet bij calamiteiten."], ["Kifid, dat bij rampen een tegemoetkoming aan reizigers uitkeert.", "Kifid behandelt klachten en keert zelf geen schade uit."], ["Het Waarborgfonds, dat schade door onvoorziene rampen opvangt.", "Het Waarborgfonds Motorverkeer gaat over verkeersschade met onverzekerde of onbekende voertuigen."]]],
["Wat is het verschil tussen een naturauitvaartverzekering en een kapitaaluitvaartverzekering?", [["Natura levert uitvaartdiensten en -goederen; kapitaal keert een geldbedrag uit.", "Bij natura krijgen nabestaanden een pakket uitvaartdiensten; bij kapitaal is het bedrag vrij te besteden."], ["Natura keert een hoger geldbedrag uit; kapitaal keert een lager bedrag uit.", "De naturaverzekering keert geen geld uit, maar levert diensten."], ["Kapitaal geldt alleen bij crematie; natura alleen bij een begrafenis.", "Het type uitvaart staat los van de vorm van de verzekering."], ["Er is geen verschil; beide termen beschrijven dezelfde geldsomverzekering.", "Het verschil tussen diensten en geld is wezenlijk."]]],
["Tot welk type verzekering behoort een kapitaaluitvaartverzekering?", [["Een levensverzekering (sommenverzekering).", "Een kapitaaluitvaartverzekering keert bij overlijden een vooraf bepaald bedrag uit en is daarmee een levensverzekering."], ["Een schadeverzekering (indemniteitsverzekering).", "De uitkering hangt niet af van een vermogensschade, maar van het overlijden."], ["Een aansprakelijkheidsverzekering voor nabestaanden.", "Er is geen aansprakelijkheid in het spel."], ["Een aanvullende zorgverzekering bij overlijden.", "Een uitvaartverzekering vergoedt geen zorgkosten."]]],
["Een klant heeft twintig jaar geleden een kapitaaluitvaartverzekering met een vast bedrag gesloten. Wat is een belangrijk aandachtspunt bij nazorg?", [["Of het verzekerde bedrag nog toereikend is voor de huidige uitvaartkosten.", "Zonder indexatie kan het vaste bedrag te laag zijn geworden; dat is een belangrijk adviespunt."], ["Of de polis inmiddels onder de WAM-verzekeringsplicht is komen te vallen.", "De WAM gaat over motorrijtuigen, niet over uitvaartverzekeringen."], ["Of de verzekering kan worden omgezet in een inboedelverzekering.", "Dat is geen zinvolle of gangbare omzetting."], ["Of er bonus-malustreden zijn opgebouwd die de premie verlagen.", "Bonus-malus speelt bij autoverzekeringen, niet bij uitvaart."]]],
["Welk informatiedocument moet een klant op grond van de IDD vóór het sluiten van een schadeverzekering ontvangen?", [["Het gestandaardiseerde informatiedocument (IPID).", "Het IPID geeft in een vaste opzet de belangrijkste kenmerken, dekkingen en uitsluitingen van een schadeverzekering."], ["Een essentiële-informatiedocument (EID) onder PRIIPs.", "Het EID is bedoeld voor verpakte beleggingsproducten, niet voor schadeverzekeringen."], ["Een Europees gestandaardiseerd informatieblad (ESIS).", "Het ESIS hoort bij hypothecair krediet."], ["Een jaaropgave met de premie en de dekkingen.", "Een jaaropgave is geen precontractueel productdocument."]]],
["Moet een distributeur onder de IDD ook bij verkoop zonder advies (execution-only) de eisen en behoeften van de klant vaststellen?", [["Ja, elke verkoop moet passen bij de eisen en behoeften van de klant.", "De IDD verplicht bij iedere distributie tot vaststelling van eisen en behoeften, ook zonder advies."], ["Nee, bij execution-only is de klant volledig zelf verantwoordelijk.", "De eisen-en-behoeftentoets geldt ook bij verkoop zonder advies."], ["Alleen als het verzekerde bedrag boven een wettelijke grens ligt.", "De IDD maakt geen onderscheid naar verzekerd bedrag."], ["Alleen bij levensverzekeringen, niet bij schadeverzekeringen.", "De verplichting geldt voor alle verzekeringen, ook schadeverzekeringen."]]],
["Welke informatie over zijn beloning moet een bemiddelaar onder de IDD vóór het sluiten van een schadeverzekering in ieder geval geven?", [["De aard van de beloning: provisie, fee of een combinatie.", "De IDD verplicht tot transparantie over de aard van de beloning, zodat de klant mogelijke belangenconflicten ziet."], ["Het jaarinkomen van de adviseur over het afgelopen jaar.", "Het inkomen van de adviseur valt niet onder de verplichte informatie."], ["De winstmarge van de verzekeraar op het betreffende product.", "Die informatie hoeft de bemiddelaar niet te verstrekken."], ["Niets, omdat beloningsinformatie alleen bij leven verplicht is.", "Informatie over de aard van de beloning is ook bij schadeverzekeringen verplicht."]]],
["Mag een adviseur provisie ontvangen voor bemiddeling in een particuliere inboedelverzekering?", [["Ja, het provisieverbod geldt niet voor deze schadeverzekering.", "Het provisieverbod geldt voor complexe producten en impactvolle producten zoals hypotheken; schadeverzekeringen vallen er niet onder."], ["Nee, provisie is sinds 2013 voor alle verzekeringen verboden.", "Het provisieverbod van 2013 geldt niet voor schadeverzekeringen."], ["Alleen als de klant daar vooraf schriftelijk om heeft gevraagd.", "Er is geen wettelijke eis dat de klant vooraf om provisie vraagt."], ["Alleen als de premie onder een wettelijk vastgesteld bedrag ligt.", "Het provisieverbod kent geen premiegrens; het hangt af van het soort product."]]],
["Een verzekeraar biedt een inboedelverzekering aan als pakket samen met een AVP. Welke informatie moet de klant op grond van de IDD dan krijgen?", [["Of de onderdelen ook afzonderlijk kunnen worden gekocht, en zo ja, wat zij los kosten.", "Bij koppelverkoop verplicht de IDD tot informatie over de mogelijkheid tot losse aankoop en de kosten per onderdeel."], ["Een overzicht van alle vergelijkbare pakketten van concurrerende verzekeraars in de markt.", "Een marktoverzicht van concurrenten is geen IDD-verplichting bij koppelverkoop."], ["Een schriftelijke goedkeuring van de AFM voor de combinatie van producten.", "De AFM keurt pakketten niet vooraf goed."], ["Een berekening van de winst die de verzekeraar op het pakket maakt.", "De winstmarge van de verzekeraar hoeft niet te worden verstrekt."]]],
["Een klant wil een doorlopende reisverzekering afsluiten. Uit inventarisatie blijkt dat hij via zijn creditcard al een reisdekking heeft. Wat past bij de zorgplicht van de adviseur?", [["De bestaande dekking analyseren en wijzen op mogelijke dubbele dekking.", "Passend advies houdt rekening met bestaande voorzieningen; dubbele dekking kost de klant onnodig premie."], ["De reisverzekering afsluiten zonder de creditcarddekking te bekijken.", "Dan voldoet het advies niet aan de inventarisatie- en zorgplicht."], ["De klant adviseren de creditcard op te zeggen om dubbele kosten te vermijden.", "De creditcard opzeggen valt buiten de vraag en is niet per se in het belang van de klant; eerst moet worden vergeleken."], ["De klant naar de creditcardmaatschappij verwijzen en zelf geen advies geven.", "De adviseur moet de bestaande dekking zelf meenemen in zijn advies."]]],
["Wat houdt het productontwikkelings- en beoordelingsproces (PARP) voor verzekeraars in?", [["Dat producten de belangen van de doelgroep evenwichtig dienen en worden getoetst.", "Het PARP vraagt dat producten kostenefficiënt, veilig, nuttig en begrijpelijk zijn voor de beoogde doelgroep."], ["Dat de AFM elk nieuw verzekeringsproduct vooraf toetst en goedkeurt voor de markt.", "De AFM keurt producten niet vooraf goed; zij houdt toezicht op het proces."], ["Dat de adviseur elk product zelf ontwikkelt voor zijn eigen klantenkring.", "Productontwikkeling ligt bij de aanbieder; de distributeur levert wel informatie."], ["Dat verzekeraars hun premies elk jaar verplicht aan de consumentenprijsindex aanpassen.", "Het PARP gaat over het dienen van klantbelangen, niet over verplichte premie-indexatie."]]],
["Wat is gangbaar als een verzekerde het niet eens is met de schadevaststelling door de expert van de verzekeraar?", [["Een eigen contra-expert inschakelen, met kostenvergoeding tot het niveau van de expert van de verzekeraar.", "Polissen bieden meestal deze regeling; boven dat bedrag alleen als de kosten redelijk zijn."], ["De schadevaststelling zonder meer accepteren, omdat de expert van de verzekeraar bindend beslist.", "De verzekerde mag een contra-expert inschakelen; de expert van de verzekeraar beslist niet bindend."], ["Direct een procedure bij de rechter beginnen, omdat een contra-expertise niet is toegestaan.", "Contra-expertise is juist gebruikelijk en toegestaan voordat een geschil naar de rechter gaat."], ["Een klacht bij de AFM indienen, die vervolgens de omvang van de schade opnieuw vaststelt.", "De AFM behandelt geen individuele schadegeschillen en stelt geen schades vast."]]],
["Wat is een belangrijke eis aan een schade-expert die door de verzekeraar wordt ingeschakeld?", [["Hij moet de schade onafhankelijk en deskundig vaststellen.", "Het Nederlands Instituut van Register Experts (NIVRE) stelt eisen aan vakbekwaamheid en gedrag."], ["Hij moet in dienst zijn van de verzekerde om belangen te waarborgen.", "Een expert van de verzekeraar werkt in opdracht van de verzekeraar; de verzekerde kan zelf een contra-expert nemen."], ["Hij moet de schade zo laag mogelijk vaststellen voor de verzekeraar.", "Een expert moet de schade objectief vaststellen, niet zo laag mogelijk."], ["Hij moet bij elke schade ook de nieuwe premie van de polis bepalen.", "De premie is geen taak van de schade-expert."]]],
["Hoe is de bewijslast meestal verdeeld bij een schadeclaim?", [["Verzekerde: gedekte gebeurtenis aannemelijk maken; verzekeraar: uitsluiting bewijzen.", "Wie een recht inroept, moet het bewijzen; een uitsluiting is een verweer van de verzekeraar."], ["De verzekeraar moet in alle gevallen bewijzen dat er geen schade is ontstaan.", "De verzekerde moet eerst zijn claim aannemelijk maken."], ["De verzekerde moet aantonen dat geen enkele uitsluiting van de polis van toepassing is.", "Het beroep op een uitsluiting moet de verzekeraar bewijzen."], ["De schade-expert draagt de volledige bewijslast voor zowel dekking als uitsluiting.", "De expert stelt de schade vast, maar is geen procespartij en draagt geen bewijslast."]]],
["Wat moet een consument doen voordat hij een klacht over zijn verzekeraar bij Kifid kan indienen?", [["Eerst bij de verzekeraar zelf klagen en diens standpunt afwachten.", "Kifid behandelt een klacht pas nadat de interne klachtenprocedure is doorlopen."], ["Eerst een procedure bij de kantonrechter beginnen en het vonnis afwachten.", "Kifid is juist een alternatief voor de rechter; een vonnis is niet nodig."], ["Eerst de AFM om toestemming vragen voor het indienen van de klacht.", "De AFM speelt geen rol bij de toegang tot Kifid."], ["Eerst de verzekering opzeggen, zodat er geen lopende relatie meer is.", "Opzegging is geen voorwaarde voor een klacht bij Kifid."]]],
["Welke financiële dienstverleners moeten zijn aangesloten bij Kifid?", [["Wft-vergunninghouders die diensten verlenen aan consumenten.", "De Wft verplicht vergunninghouders met consumentendienstverlening tot aansluiting bij een erkende geschilleninstantie, in de praktijk Kifid."], ["Alleen banken die betaal- en spaarrekeningen aan consumenten aanbieden.", "Ook verzekeraars en adviseurs moeten zijn aangesloten."], ["Alleen dienstverleners met meer dan vijftig werknemers.", "Er geldt geen grens naar aantal werknemers."], ["Geen enkele; aansluiting bij Kifid is altijd vrijwillig.", "Aansluiting is wettelijk verplicht voor consumentendienstverlening."]]],
["Wat kan Kifid NIET doen?", [["Boetes opleggen aan financiële dienstverleners.", "Boetes zijn een bevoegdheid van toezichthouders zoals de AFM; Kifid beslecht geschillen."], ["Een uitspraak doen in een geschil tussen consument en verzekeraar.", "Dat is de kerntaak van de Geschillencommissie."], ["Bemiddelen tussen consument en verzekeraar.", "Kifid probeert vaak eerst te bemiddelen."], ["In hoger beroep een geschil behandelen via de Commissie van Beroep.", "De Commissie van Beroep is onderdeel van Kifid."]]],
["Wat is de belangrijkste functie van Stichting CIS?", [["Centrale databanken beheren voor risicobeoordeling en fraudebestrijding.", "Verzekeraars raadplegen CIS bij acceptatie en schadebehandeling, binnen de privacyregels."], ["Klachten van consumenten over verzekeraars bindend behandelen.", "Klachten worden behandeld door de verzekeraar en daarna Kifid."], ["Toezicht houden op de solvabiliteit van particuliere schade- en levensverzekeraars.", "Prudentieel toezicht ligt bij DNB."], ["Terrorismeschade herverzekeren voor aangesloten verzekeraars.", "Dat is de rol van de NHT."]]],
["Een consument wil weten welke gegevens over hem bij Stichting CIS zijn geregistreerd. Wat kan hij doen?", [["Een inzageverzoek indienen bij CIS op grond van de AVG.", "Iedereen heeft onder de AVG het recht te weten welke persoonsgegevens over hem worden verwerkt."], ["Niets; CIS-gegevens zijn geheim voor consumenten.", "De AVG geeft wel een recht op inzage."], ["Een verzoek indienen bij de AFM.", "De AFM beheert de CIS-gegevens niet."], ["Een rechtszaak beginnen, omdat inzage alleen via de rechter mogelijk is.", "Inzage kan zonder rechter; een inzageverzoek bij CIS is de aangewezen weg."]]],
["Wat is de rol van de Nederlandse Herverzekeringsmaatschappij voor Terrorismeschaden (NHT)?", [["Zij herverzekert terrorismeschade voor verzekeraars, tot een jaarlijks maximum.", "Via de NHT kunnen verzekeraars terrorismeschade dekken; de uitkering wordt bepaald volgens het uitkeringsprotocol."], ["Zij keert terrorismeschade rechtstreeks uit aan onverzekerde consumenten en bedrijven.", "De NHT keert uit aan verzekeraars, niet rechtstreeks aan onverzekerde consumenten of bedrijven."], ["Zij houdt namens DNB toezicht op de solvabiliteit van verzekeraars.", "Toezicht ligt bij AFM en DNB; de NHT is een herverzekeraar."], ["Zij herverzekert overstromingsschade door het bezwijken van dijken.", "Overstroming is een ander risico; de NHT gaat over terrorisme."]]],
["Welke vormen van molest worden in Nederlandse polissen standaard uitgesloten?", [["Gewapend conflict, burgeroorlog, opstand, binnenlandse onlusten, oproer en muiterij.", "Dit zijn de zes vaste vormen van molest volgens de gangbare definitie van het Verbond van Verzekeraars."], ["Terrorisme, kwaadwillige besmetting, sabotage, gijzeling, ontvoering en cyberaanvallen.", "Terrorisme en verwante risico's vallen onder de terrorismeclausule en de NHT, niet onder de molestdefinitie."], ["Inbraak, diefstal, vandalisme, beroving, afpersing en brandstichting door derden.", "Dit zijn gewone (al dan niet gedekte) gevaren, geen molest."], ["Storm, hagel, overstroming, aardbeving, vulkanische uitbarsting en blikseminslag.", "Dit zijn natuurgevaren, geen molest."]]],
["Welke overstromingsschade is bij woonhuis- en inboedelpolissen in Nederland doorgaans NIET gedekt?", [["Schade door het bezwijken van een primaire waterkering, zoals een zeedijk.", "Dit catastroferisico is meestal uitgesloten; overstroming door een niet-primaire (regionale) kering is in veel polissen wel gedekt."], ["Schade door hevige regen die onvoorzien via het dak de woning binnenstroomt.", "Neerslagschade is in veel polissen juist gedekt."], ["Schade door een gesprongen waterleiding in de woning tijdens vorst.", "Leidingwater is een standaard gedekt gevaar."], ["Schade door het bezwijken van een kleine regionale kering langs een polder.", "Veel polissen dekken dit tegenwoordig wel."]]],
["Wat geldt voor een tegemoetkoming onder de Wet tegemoetkoming schade bij rampen (Wts)?", [["Er is geen tegemoetkoming voor schade die redelijkerwijs verzekerbaar was.", "De Wts is een vangnet voor niet-verzekerbare schade en wordt per ramp van toepassing verklaard."], ["De Wts vergoedt alle schade, ook als de klant een verzekering had kunnen afsluiten.", "Verzekerbare schade is juist uitgesloten."], ["De Wts is een verplichte verzekering voor huiseigenaren.", "De Wts is een overheidsregeling, geen verzekering."], ["De Wts geldt automatisch bij elke storm.", "De Wts moet per ramp van toepassing worden verklaard."]]],
["Wat betekent 'herstel gaat voor vervangen' bij duurzame schadebehandeling?", [["Repareren waar mogelijk in plaats van vervangen, om grondstoffen te besparen.", "Steeds meer verzekeraars sturen op herstel, mits de kwaliteit gelijkwaardig is."], ["De verzekerde moet beschadigde zaken voortaan altijd zelf en op eigen kosten herstellen.", "Herstel wordt door of via de verzekeraar geregeld en niet aan de verzekerde opgelegd."], ["Vervanging van beschadigde zaken is wettelijk niet meer toegestaan.", "Vervanging blijft mogelijk als herstel niet zinvol is."], ["Herstel is verplicht omdat het in alle gevallen goedkoper is.", "Duurzaamheid, niet kosten, is het uitgangspunt."]]],
["Bij welk product moet een adviseur onder de IDD-regels de duurzaamheidsvoorkeuren van de klant uitvragen?", [["Bij advies over verzekeringsgebaseerde beleggingsproducten.", "De verplichting tot het uitvragen van duurzaamheidsvoorkeuren geldt voor beleggingsverzekeringen, niet voor schadeverzekeringen."], ["Bij advies over een inboedel- of woonhuisverzekering.", "Voor schadeverzekeringen bestaat deze uitvraagplicht niet."], ["Bij advies over een WA- of cascoverzekering voor de auto.", "Ook hier geldt de uitvraagplicht niet."], ["Bij advies over een doorlopende reis- en annuleringsverzekering.", "Een reisverzekering is geen beleggingsproduct."]]],
["Een adviseur bemiddelt uitsluitend in particuliere schadeverzekeringen. Valt hij onder de Wwft?", [["Nee, de Wwft wijst alleen bemiddelaars in levensverzekeringen aan.", "De Wwft-verplichtingen gelden voor bemiddelaars in levensverzekeringen, niet voor pure schadebemiddelaars."], ["Ja, de Wwft geldt voor alle financiële dienstverleners met een vergunning.", "De Wwft geldt alleen voor aangewezen instellingen."], ["Ja, zodra de jaarpremie van een klant een wettelijke grens overschrijdt.", "De Wwft kent geen premiegrens die schadebemiddeling onder de wet brengt."], ["Nee, de Wwft geldt uitsluitend voor banken en betaalinstellingen.", "De Wwft geldt ook voor andere instellingen, waaronder bemiddelaars in levensverzekeringen."]]],
["Binnen welke termijn moet een organisatie een datalek dat een risico vormt voor betrokkenen melden bij de Autoriteit Persoonsgegevens?", [["Binnen 72 uur na ontdekking.", "De AVG verplicht tot melding zonder onredelijke vertraging en uiterlijk binnen 72 uur."], ["Binnen 14 dagen.", "Veertien dagen is te laat onder de AVG."], ["Binnen een maand.", "Een maand is de termijn voor het beantwoorden van een inzageverzoek, niet voor een datalekmelding."], ["Alleen als de verzekerde daarom vraagt.", "De meldplicht geldt los van een verzoek van de betrokkene."]]],
["Bij letselschade verwerkt een verzekeraar medische gegevens. Wat is daarvoor gebruikelijk om de privacy te waarborgen?", [["Beoordeling door een medisch adviseur met medisch beroepsgeheim.", "Gezondheidsgegevens zijn bijzondere persoonsgegevens; toegang is beperkt tot de medisch adviseur en wie dat strikt nodig heeft."], ["Inzage door alle schadebehandelaars die aan het dossier werken.", "Toegang tot gezondheidsgegevens moet strikt worden beperkt."], ["Doorsturen van het volledige medische dossier naar de tegenpartij.", "Delen met de tegenpartij zonder noodzaak en toestemming is in strijd met de AVG."], ["Opslag in een gezamenlijke databank die alle verzekeraars inzien.", "Zo'n gedeelde medische databank is in strijd met dataminimalisatie en het medisch beroepsgeheim."]]],
["Wat is bij een schadeverzekering het verschil tussen de verzekeringnemer en de verzekerde?", [["De verzekeringnemer is de contractpartij; de verzekerde is degene wiens belang is gedekt.", "De verzekeringnemer is contractpartij van de verzekeraar; de verzekerde is de persoon die de schade lijdt en recht heeft op uitkering. Vaak is dat dezelfde persoon, maar niet altijd."], ["Er is geen verschil; beide begrippen duiden in BW 7 altijd op dezelfde persoon.", "Dat klopt niet: bij een gezins-AVP zijn bijvoorbeeld ook partner en kinderen verzekerd, terwijl alleen één persoon verzekeringnemer is."], ["De verzekerde sluit de overeenkomst; de verzekeringnemer is degene die de uitkering na een schade ontvangt.", "Dit draait de rollen om: de verzekeringnemer is juist de contractpartij die de verzekering aangaat."], ["De verzekeringnemer is de tussenpersoon die de verzekering namens de klant bij de verzekeraar onderbrengt.", "Een tussenpersoon bemiddelt, maar is geen partij bij de verzekeringsovereenkomst en dus geen verzekeringnemer."]]],
["Meneer Pieters sluit op maandag een cascoverzekering. Beide partijen weten dat zijn auto zondag al bij een aanrijding is beschadigd. Wat geldt voor die schade?", [["Geen dekking, omdat bij het sluiten al vaststond dat deze schade was ontstaan.", "Een verzekering vereist onzekerheid over het ontstaan van schade. Een schade die bij het sluiten al zeker was, kan niet meer worden verzekerd."], ["Volledige dekking, omdat de verzekeraar de schade kende en de verzekering toch heeft geaccepteerd.", "Kennis van de verzekeraar maakt een zekere schade niet verzekerbaar; het onzekerheidsvereiste ontbreekt nog steeds voor deze gebeurtenis."], ["Gedeeltelijke dekking naar verhouding van de premie die over de eerste dag is betaald.", "Een evenredige uitkering hoort bij schending van de mededelingsplicht, niet bij een schade die al vóór het sluiten vaststond."], ["Dekking, mits de schade binnen veertien dagen na het sluiten van de verzekering wordt gemeld.", "Een tijdige melding verandert niets aan het feit dat er bij het sluiten geen onzekerheid meer was over deze schade."]]],
["Hoe komt een verzekeringsovereenkomst volgens het Burgerlijk Wetboek tot stand?", [["Door aanbod en aanvaarding; de polis die de verzekeraar daarna afgeeft dient als bewijs.", "De overeenkomst is vormvrij en ontstaat zodra partijen het eens zijn. De verzekeraar moet wel een polis opmaken, maar die is bewijs en geen voorwaarde voor het bestaan."], ["Pas wanneer de verzekeringnemer de polis heeft ontvangen en ondertekend teruggestuurd.", "Ondertekening van de polis is geen wettelijk vereiste; de overeenkomst bestaat al vanaf de wilsovereenstemming."], ["Pas na betaling van de eerste premie, omdat de overeenkomst daarvóór niet rechtsgeldig is.", "Premiebetaling is een verplichting uit de overeenkomst, geen voorwaarde voor het ontstaan ervan."], ["Uitsluitend door een schriftelijke akte, omdat de wet voor verzekeringen een vormvereiste stelt.", "De wet stelt geen vormvereiste; een verzekering kan ook mondeling, telefonisch of online worden gesloten."]]],
["Een verzekeringnemer meldt een eerder schadeverleden niet, maar de verzekeraar wist daar al van uit zijn eigen administratie. Kan de verzekeraar zich op schending van de mededelingsplicht beroepen?", [["Nee, de verzekeraar kan geen beroep doen op feiten die hij al kende of behoorde te kennen.", "De mededelingsplicht beschermt de verzekeraar tegen onbekende risicofactoren. Wat hij al wist of had moeten weten, kan hij de klant niet tegenwerpen."], ["Ja, de verzekeringnemer moet relevante feiten altijd zelf melden, ongeacht wat de verzekeraar al weet.", "De wet sluit een beroep op schending juist uit voor feiten die de verzekeraar kent of behoort te kennen."], ["Ja, maar alleen als de verzekeraar binnen twee maanden na het sluiten van de verzekering een schade heeft.", "De termijn van twee maanden gaat over het moment waarop de verzekeraar na ontdekking moet reageren, niet over een beperking als deze."], ["Alleen als het schadeverleden bij een andere verzekeraar is ontstaan dan bij de huidige.", "Waar de schade is ontstaan doet niet ter zake; beslissend is of de verzekeraar het feit al kende of behoorde te kennen."]]],
["Na een brand blijkt dat de verzekeringnemer zonder opzet een eerdere brandstichting in zijn woning niet heeft gemeld. De verzekeraar toont aan dat hij de verzekering bij juiste melding helemaal niet zou hebben gesloten. Wat is het gevolg?", [["De verzekeraar hoeft niets uit te keren.", "Als de verzekeraar bij kennis van de ware stand van zaken geen verzekering zou hebben gesloten, is hij volgens de wet niet tot uitkering verplicht, ook zonder opzet van de klant."], ["De verzekeraar keert uit naar verhouding van de premie, net als bij een te lage premie.", "De evenredigheidsregel geldt als de verzekeraar wel zou hebben verzekerd tegen een hogere premie, niet als hij helemaal niet zou hebben verzekerd."], ["De verzekeraar moet volledig uitkeren, omdat er geen opzet tot misleiding was en de premie is betaald.", "Ontbreken van opzet voorkomt alleen de zwaarste sanctie; als de verzekeraar nooit zou hebben verzekerd, vervalt het recht op uitkering toch."], ["De verzekeraar keert de helft uit, omdat de schuld gedeeld wordt tussen klant en verzekeraar.", "De wet kent geen vaste verdeling van de helft; de gevolgen hangen af van wat de verzekeraar bij juiste melding zou hebben gedaan."]]],
["De verzekeraar toont na een schade aan dat hij bij juiste melding van een niet-gemeld feit een hoger eigen risico zou hebben bedongen, tegen dezelfde premie. Er was geen opzet. Wat geldt?", [["De verzekeraar keert uit alsof dat hogere eigen risico van het begin af aan was afgesproken.", "Bij andere voorwaarden dan een hogere premie wordt de schade vergoed alsof die voorwaarden hadden gegolden; de klant wordt zo geplaatst in de situatie van een juiste melding."], ["De verzekeraar keert niets uit, omdat de verzekeringnemer de mededelingsplicht heeft geschonden.", "Een volledige weigering geldt alleen bij opzet tot misleiding of als de verzekeraar helemaal niet zou hebben verzekerd."], ["De verzekeraar keert volledig uit zonder eigen risico, omdat de premie niet anders zou zijn geweest.", "Dat de premie gelijk zou zijn gebleven, betekent niet dat de klant het voordeel van het lagere eigen risico mag houden."], ["De verzekeraar keert uit naar verhouding van de betaalde premie tot de juiste premie.", "De evenredigheidsregel past bij een hogere premie; hier zou alleen het eigen risico anders zijn, en dan geldt dat afwijkende eigen risico."]]],
["Wat geldt in beginsel voor het melden van strafrechtelijke feiten bij het aangaan van een verzekering?", [["Feiten van meer dan acht jaar vóór het sluiten hoeven in beginsel niet te worden gemeld.", "De wet beperkt de mededelingsplicht voor strafrechtelijke feiten in de tijd; oude feiten van meer dan acht jaar geleden hoeven in beginsel niet te worden genoemd."], ["Alle strafrechtelijke feiten moeten worden gemeld, hoe lang geleden ze ook hebben plaatsgevonden.", "De wet kent juist een termijn van acht jaar, zodat iemand niet levenslang door een oud strafrechtelijk verleden wordt achtervolgd."], ["Strafrechtelijke feiten hoeven nooit te worden gemeld, omdat die onder de privacywetgeving vallen.", "Strafrechtelijke feiten kunnen wel degelijk relevant zijn voor het risico en vallen binnen de termijn onder de mededelingsplicht."], ["Alleen veroordelingen tot een gevangenisstraf van meer dan vier jaar hoeven te worden gemeld.", "Zo'n strafmaatgrens bestaat niet in de regeling van de mededelingsplicht; de wet werkt met een tijdsgrens van acht jaar."]]],
["Een verzekeraar neemt in zijn voorwaarden op dat elke onjuiste mededeling bij het aanvragen, ook zonder opzet, leidt tot verval van alle rechten. Wat geldt hiervoor?", [["Het beding is ongeldig; hiervan mag niet ten nadele van de verzekeringnemer worden afgeweken.", "De regeling van de mededelingsplicht is semidwingend recht: afwijken mag alleen in het voordeel van de verzekeringnemer, niet in zijn nadeel."], ["Dit beding is geldig, omdat partijen bij een schadeverzekering volledige contractvrijheid hebben.", "Voor de mededelingsplicht geldt geen volledige contractvrijheid; de wet beschermt de verzekeringnemer tegen strengere bedingen."], ["Dit beding is alleen geldig als het in de polis is vetgedrukt en de klant er apart voor heeft getekend.", "Opvallende vormgeving of een handtekening maakt een beding dat afwijkt van semidwingend recht niet alsnog geldig."], ["Dit beding is geldig bij consumenten, maar niet bij verzekeringen die een bedrijf afsluit.", "Het omgekeerde is eerder waar: de wettelijke bescherming is juist bedoeld voor de verzekeringnemer, en geldt zeker bij consumenten."]]],
["Wanneer is volgens de rechtspraak sprake van roekeloosheid in de zin van de wettelijke uitsluiting bij schadeverzekeringen?", [["Als de verzekerde zich bewust was van de aanmerkelijke kans op schade en dat risico toch heeft genomen.", "Het gaat om bewuste roekeloosheid: de verzekerde besefte het gevaar en accepteerde het. Gewone onoplettendheid valt daar niet onder."], ["Als de verzekerde een kleine vergissing maakt die achteraf gezien had kunnen worden voorkomen.", "Een vergissing of gewone onvoorzichtigheid is geen roekeloosheid; anders zou vrijwel elke schade zijn uitgesloten."], ["Als de verzekerde de schade niet binnen de in de polis genoemde termijn bij de verzekeraar heeft gemeld.", "Te late melding is een schending van de meldingsplicht met eigen gevolgen; het zegt niets over het ontstaan van de schade."], ["Als de schade groter is dan de verzekeringnemer bij het sluiten van de verzekering had voorzien.", "De omvang van de schade bepaalt niet of er roekeloosheid is; het gaat om het gedrag en het bewustzijn van de verzekerde."]]],
["Mevrouw Kok en haar partner zijn beiden verzekerd op een inboedelpolis. Haar partner sticht na een ruzie opzettelijk brand. Mevrouw Kok wist van niets. Wat is volgens de wet het uitgangspunt?", [["Mevrouw Kok behoudt in beginsel haar recht; de wettelijke opzetuitsluiting geldt per verzekerde.", "De wettelijke uitsluiting treft alleen de verzekerde die de schade met opzet of roekeloosheid veroorzaakte. Polissen kunnen dit wel uitbreiden tot medeverzekerden."], ["Geen van beiden heeft recht op uitkering, omdat de wet opzet van één verzekerde aan alle verzekerden toerekent.", "De wet rekent opzet niet automatisch toe aan andere verzekerden; dat kan alleen voortvloeien uit een bepaling in de polis."], ["Beiden hebben recht op volledige uitkering, omdat opzet bij een inboedelverzekering niet kan worden uitgesloten.", "De partner die opzettelijk brand stichtte, heeft volgens de wet geen recht op uitkering; de uitsluiting is juist wettelijk geregeld."], ["Mevrouw Kok ontvangt alleen een uitkering als haar partner strafrechtelijk is veroordeeld voor de brandstichting.", "Een strafrechtelijke veroordeling is geen voorwaarde; de verzekeraar moet de opzet in de civiele procedure aannemelijk maken."]]],
["Welke plicht heeft een verzekerde volgens BW 7 zodra een gedekte schade dreigt of is ontstaan?", [["Naar vermogen redelijke maatregelen nemen om de schade te voorkomen of te beperken.", "Dit is de bereddingsplicht. Schendt de verzekerde die en lijdt de verzekeraar daardoor nadeel, dan kan de uitkering met dat nadeel worden verminderd."], ["Niets doen tot de expert van de verzekeraar de schade heeft bekeken, zodat er geen bewijs verloren gaat.", "Afwachten kan de schade juist vergroten; de verzekerde moet direct redelijke maatregelen nemen en kan het bewijs vastleggen met foto's."], ["De schade binnen 24 uur volledig laten herstellen door een vakman, zodat er geen gevolgschade ontstaat.", "Volledig herstel vóór beoordeling is geen wettelijke plicht en kan de schadevaststelling juist bemoeilijken."], ["De schade direct bij de politie melden, ook als er geen sprake is van een strafbaar feit.", "Aangifte is relevant bij bijvoorbeeld diefstal of vandalisme, maar is geen algemene wettelijke verplichting bij elke dreigende schade."]]],
["Tijdens een storm waait een deel van het dak van de woning van de familie Bos. Meneer Bos laat dezelfde avond een dekzeil plaatsen om inregenen te voorkomen. Hoe worden de kosten van het dekzeil behandeld?", [["Als bereddingskosten: ze worden vergoed omdat ze zijn gemaakt om dreigende gedekte schade te beperken.", "Het dekzeil voorkomt verdere waterschade door een gedekte stormschade. Zulke redelijke kosten bij onmiddellijk dreigend gevaar vallen onder beredding."], ["Als onderhoudskosten: die komen altijd voor rekening van de eigenaar van de woning zelf.", "Onderhoud is periodieke zorg voor de woning; hier gaat het om een noodmaatregel na een gedekte gebeurtenis, en dat is beredding."], ["Ze worden alleen vergoed als de verzekeraar vooraf schriftelijk toestemming heeft gegeven voor het plaatsen.", "De wet vraagt geen voorafgaande toestemming voor redelijke bereddingskosten; die toestemming is in een noodsituatie ook vaak niet te krijgen."], ["Ze worden niet vergoed, omdat er op het moment van plaatsen nog geen waterschade aan de inboedel was.", "Beredding is juist bedoeld om schade te voorkomen voordat die ontstaat; dat er nog geen waterschade was, is daarom geen reden voor weigering."]]],
["Een benadeelde stelt een verzekerde aansprakelijk. De AVP-verzekeraar voert namens de verzekerde verweer in een procedure. Wie draagt de kosten van dat verweer?", [["De verzekeraar, ook als daardoor samen met de schadevergoeding de verzekerde som wordt overschreden.", "Bij een aansprakelijkheidsverzekering komen de kosten van verweer die met instemming van de verzekeraar worden gemaakt voor zijn rekening, zo nodig boven de verzekerde som."], ["De verzekerde zelf, omdat een AVP alleen de schadevergoeding aan de benadeelde dekt en geen kosten.", "De wet en de polissen gaan er juist van uit dat de verzekeraar het verweer voert en de kosten daarvan draagt."], ["De verzekeraar, maar alleen tot het bedrag dat na aftrek van de schadevergoeding van de verzekerde som overblijft.", "Verweerkosten worden niet beperkt tot het restant van de verzekerde som; ze komen daar zo nodig bovenop."], ["De benadeelde, omdat die de procedure begint en daarmee het risico van de kosten op zich neemt.", "Een benadeelde kan bij verlies in een proceskostenveroordeling worden betrokken, maar de eigen verweerkosten van de verzekerde draagt de verzekeraar."]]],
["Een consument sluit een autoverzekering met een contractduur van één jaar. Na vier maanden wil hij overstappen. Wat is het uitgangspunt?", [["Hij kan in beginsel pas tegen het einde van de eerste contractperiode opzeggen, tenzij de polis meer ruimte geeft.", "Het wettelijke recht om op elk moment met hooguit een maand opzegtermijn op te zeggen geldt pas na stilzwijgende verlenging; in de eerste periode geldt de afgesproken looptijd."], ["Hij kan op elk moment opzeggen met een opzegtermijn van ten hoogste één maand, ook in het eerste jaar.", "Dat recht geldt voor de consument na stilzwijgende verlenging van de eerste contractperiode, niet automatisch tijdens die eerste periode."], ["Hij kan nooit tussentijds opzeggen, ook niet na verlenging, omdat een autoverzekering een verplichte verzekering is.", "Ook verplichte WA-verzekeringen zijn na verlenging maandelijks opzegbaar; de klant moet dan wel elders verzekerd zijn."], ["Hij kan alleen opzeggen als hij de premie over de hele resterende looptijd en een boete vooraf betaalt.", "De wet kent geen boete voor opzegging; de vraag is alleen wanneer opzegging mogelijk is."]]],
["Wat houdt voorlopige dekking in?", [["Tijdelijke dekking tijdens de beoordeling van de aanvraag, tot de verzekeraar beslist.", "Zo is de klant al verzekerd terwijl de aanvraag wordt beoordeeld. Bij weigering eindigt de dekking, meestal na een korte termijn."], ["Dekking die pas ingaat als de verzekeraar de aanvraag heeft beoordeeld en de polis heeft verzonden.", "Dat beschrijft de definitieve dekking; voorlopige dekking is er juist vóór die beoordeling."], ["Een gedeeltelijke dekking waarbij schaden tijdens de acceptatieperiode voor de helft worden vergoed.", "Voorlopige dekking is geen gedeeltelijke dekking; binnen de afgesproken voorwaarden geldt de gewone dekking."], ["Dekking die uitsluitend geldt voor schaden die al vóór de aanvraag bekend waren bij de verzekeringnemer.", "Bekende schaden zijn juist niet te verzekeren; voorlopige dekking betreft onzekere toekomstige gebeurtenissen."]]],
["Een klant is voor dezelfde fiets verzekerd via zijn inboedelpolis en via een aparte fietsverzekering. Beide polissen bepalen dat zij geen dekking bieden als de schade elders is verzekerd. Wat geldt?", [["De bedingen vallen tegen elkaar weg; de verzekeraars dragen de schade samen.", "Als beide polissen naar elkaar verwijzen, zou de klant nergens dekking hebben. De wet voorkomt dat: de verzekerde krijgt vergoeding en de verzekeraars verdelen de schade."], ["De klant krijgt geen vergoeding, omdat beide verzekeraars zich op hun samenloopbeding kunnen beroepen.", "Dat zou betekenen dat iemand die dubbel premie betaalt minder krijgt dan iemand met één verzekering; de wet laat dit niet toe."], ["De klant krijgt zijn schade van beide verzekeraars volledig vergoed, dus twee keer.", "Dubbele vergoeding is in strijd met het indemniteitsbeginsel; de schade wordt één keer vergoed."], ["Alleen de oudste polis keert uit; de jongste verzekering is nietig wegens dubbele verzekering.", "Een latere verzekering wordt door samenloop niet nietig; de vraag is alleen hoe de schade wordt verdeeld."]]],
["Een verzekering eindigt halverwege het premiejaar, bijvoorbeeld omdat de verzekerde auto is verkocht. Wat geldt in beginsel voor de vooruitbetaalde premie?", [["De verzekeringnemer krijgt de premie over de resterende periode terug.", "Bij tussentijdse beëindiging heeft de verzekeringnemer in beginsel recht op teruggave van premie naar tijdsevenredigheid, behalve bij bijvoorbeeld opzet tot misleiding."], ["De premie blijft bij de verzekeraar, omdat die voor een volledig jaar risico heeft gereserveerd.", "De verzekeraar loopt na het einde geen risico meer; het behouden van premie zonder tegenprestatie is in beginsel niet toegestaan."], ["De verzekeringnemer krijgt alleen premie terug als hij in het lopende jaar geen schade heeft gemeld.", "Een eerdere schademelding is in beginsel geen reden om de premie over de resterende periode in te houden."], ["De premie wordt omgezet in een tegoed dat alleen bij dezelfde verzekeraar kan worden gebruikt.", "De verzekeringnemer heeft recht op teruggave; een verplicht tegoed bij dezelfde verzekeraar volgt niet uit de wet."]]],
["Twee auto's botsen op een kruispunt. Op welke grondslag wordt de aansprakelijkheid tussen de twee automobilisten beoordeeld?", [["Op de algemene regels van onrechtmatige daad, dus op basis van schuld.", "De bijzondere bescherming van art. 185 WVW geldt voor niet-gemotoriseerde verkeersdeelnemers; tussen motorrijtuigen onderling geldt gewone schuldaansprakelijkheid."], ["Op art. 185 WVW, zodat de bestuurder met de zwaarste auto in beginsel aansprakelijk is.", "Art. 185 WVW beschermt voetgangers en fietsers tegen motorrijtuigen; het is niet van toepassing tussen twee motorrijtuigen."], ["Elke partij draagt altijd de eigen schade, ongeacht wie de aanrijding heeft veroorzaakt.", "Wie de aanrijding door een fout veroorzaakt, is aansprakelijk; er geldt geen algemene regel dat ieder zijn eigen schade draagt."], ["De bestuurder die van rechts kwam, is altijd voor 50% aansprakelijk vanwege de voorrangsregels.", "Voorrangsregels spelen een rol bij het vaststellen van de fout, maar er bestaat geen vaste aansprakelijkheid van 50% voor een bepaalde partij."]]],
["Lotte rijdt als passagier mee in de auto van haar vriend. Door zijn fout botst hij tegen een vrachtwagen en raakt Lotte gewond. Via welke verzekering komt haar letselschade in de eerste plaats voor vergoeding in aanmerking?", [["De WA-verzekering van de auto waarin zij meereed.", "De WA-verzekering dekt de aansprakelijkheid van de bestuurder tegenover derden, en passagiers zijn derden. Alleen de schade van de bestuurder zelf valt erbuiten."], ["Haar eigen AVP, omdat zij als particulier aan het verkeer deelnam.", "Een AVP dekt de aansprakelijkheid van Lotte zelf tegenover anderen, niet haar eigen letselschade."], ["Haar eigen rechtsbijstandverzekering, die de letselschade als eerste vergoedt.", "Een rechtsbijstandverzekering helpt bij verhaal, maar vergoedt zelf geen letselschade."], ["Niemand, omdat passagiers op eigen risico in een auto meerijden.", "Een passagier rijdt niet op eigen risico mee; zij is een derde tegenover de bestuurder en diens WA-verzekering."]]],
["Daan leent de auto van zijn buurman en veroorzaakt een aanrijding waarbij een andere auto wordt beschadigd. Welke verzekering vergoedt de schade aan de andere auto?", [["De WA-verzekering van de auto van de buurman.", "De WA-dekking hoort bij het motorrijtuig en dekt ook de aansprakelijkheid van iedere bestuurder die er met toestemming in rijdt. Wel kan de buurman terugvallen op de bonus-malusladder."], ["De AVP van Daan, omdat hij niet de kentekenhouder is.", "Aansprakelijkheid met een motorrijtuig is in een AVP uitgesloten; die hoort onder de WA-verzekering van het voertuig."], ["De WA-verzekering van een eventuele eigen auto van Daan, die altijd voorgaat.", "De verzekering van Daans eigen auto ziet op dat voertuig; de schade met de geleende auto valt onder de WA van die auto."], ["Niemand, omdat een niet-opgegeven bestuurder nooit onder de WA-verzekering valt.", "De WAM beschermt benadeelden ongeacht wie rijdt; de verzekering dekt ook de aansprakelijkheid van incidentele bestuurders."]]],
["Daan rijdt bij het parkeren tegen een muur met de geleende auto van zijn buurman. De auto heeft alleen een WA-verzekering. Wat geldt voor de schade aan de auto zelf?", [["Die is niet gedekt; ook de AVP van Daan sluit schade met en aan motorrijtuigen uit.", "De WA dekt alleen schade aan derden, niet aan de verzekerde auto. De AVP sluit motorrijtuigen uit, zodat Daan de schade zelf moet vergoeden."], ["Die wordt vergoed door de WA-verzekering, omdat Daan niet de eigenaar is van de auto.", "De WA-dekking is beperkt tot schade aan anderen; de auto zelf is nooit derde ten opzichte van zijn eigen WA-verzekering."], ["Die valt onder de AVP van Daan, omdat het om schade aan een zaak van een ander gaat.", "De AVP sluit schade met en aan motorrijtuigen uit, en daarnaast vaak schade aan zaken onder opzicht."], ["Die wordt vergoed door het Waarborgfonds Motorverkeer.", "Het Waarborgfonds komt op voor slachtoffers van onbekende of onverzekerde motorrijtuigen, niet voor eigen schade aan een verzekerde auto."]]],
["Ouders sluiten de autoverzekering op eigen naam af en geven zichzelf op als regelmatige bestuurder, terwijl hun zoon van 19 jaar vrijwel altijd in de auto rijdt. Hoe moet dit worden beoordeeld?", [["Als een onjuiste mededeling over de regelmatige bestuurder, met mogelijke gevolgen voor de uitkering.", "De leeftijd en rijervaring van de regelmatige bestuurder zijn relevant voor premie en acceptatie. Bewust een ander opgeven kan zelfs worden gezien als opzet tot misleiding."], ["Als toegestaan, omdat de ouders kentekenhouder zijn en de WA-verzekering altijd bij het voertuig hoort.", "Dat de verzekering bij het voertuig hoort, maakt een onjuiste opgave van de regelmatige bestuurder niet toelaatbaar."], ["Als slim premieadvies, omdat de verzekeraar bij een schade toch niet kan nagaan wie meestal rijdt.", "Verzekeraars onderzoeken dit wel, en een adviseur die dit aanraadt, handelt in strijd met zijn zorgplicht en integriteit."], ["Als een kwestie die alleen gevolgen heeft voor de bonus-malustrede van de zoon.", "De zoon bouwt hier geen eigen trede op, en de gevolgen gaan verder: het betreft de mededelingsplicht en mogelijk fraude."]]],
["Waarvoor dient de groene kaart, het internationale verzekeringsbewijs voor motorrijtuigen?", [["Als bewijs van een geldige WA-verzekering in de landen van het groenekaartsysteem.", "De groene kaart toont aan dat aan de verzekeringsplicht in het bezochte land is voldaan; op de kaart staat in welke landen de dekking geldt."], ["Als bewijs dat het voertuig in het buitenland ook tegen diefstal en eigen schade is verzekerd.", "De groene kaart gaat over de verplichte aansprakelijkheidsverzekering, niet over cascodekking."], ["Als vervanging van het kentekenbewijs wanneer de bestuurder in een land buiten de Europese Unie rijdt.", "Het kentekenbewijs blijft nodig; de groene kaart is een verzekeringsbewijs en geen registratiedocument."], ["Als bewijs dat de bestuurder een internationaal rijbewijs heeft voor de landen die op de kaart staan.", "Een rijbewijs gaat over de bevoegdheid van de bestuurder; de groene kaart over de verzekering van het voertuig."]]],
["Meneer Hendriks zet zijn oldtimer voor een jaar in de garage en laat het kenteken bij de RDW schorsen. Wat betekent dit voor de verzekeringsplicht?", [["Er geldt dan geen verzekeringsplicht, maar het voertuig mag niet op de openbare weg komen.", "Een geschorst voertuig mag niet aan het verkeer deelnemen of op de openbare weg geparkeerd staan; daarom vervalt de verplichting tot WA-verzekering voor die periode."], ["De WAM-verzekeringsplicht blijft bestaan, omdat die geldt zolang er een kentekenhouder is ingeschreven.", "Juist door de schorsing vervalt de verzekeringsplicht tijdelijk; het voertuig mag dan niet op de openbare weg komen."], ["Hij mag tijdens de schorsing op de openbare weg rijden, mits hij een AVP heeft afgesloten.", "Rijden met een geschorst voertuig is niet toegestaan, en een AVP dekt geen aansprakelijkheid met motorrijtuigen."], ["De verzekeringsplicht gaat tijdens de schorsing over op de RDW, die het risico van het voertuig draagt.", "De RDW registreert de schorsing maar neemt geen enkel risico over; het voertuig mag eenvoudigweg niet aan het verkeer deelnemen."]]],
["Mevrouw Smits wordt tijdens een vakantie in Duitsland aangereden door een Duitse automobilist, die de schuld heeft. Hoe kan zij haar schade het eenvoudigst afwikkelen?", [["Via de schaderegelaar die de Duitse WA-verzekeraar in Nederland moet hebben aangewezen.", "Europese regels verplichten WA-verzekeraars om in elk lidstaat een schaderegelaar te hebben, zodat een benadeelde zijn schade in eigen land en taal kan afwikkelen."], ["Uitsluitend door een procedure te beginnen bij de Duitse rechter tegen de bestuurder persoonlijk.", "Een procedure in Duitsland is niet nodig; de benadeelde kan via de schaderegelaar in Nederland bij de verzekeraar terecht."], ["Via haar eigen WA-verzekeraar, die haar schade vergoedt en die later verhaalt op de Duitse verzekeraar.", "Haar eigen WA-verzekering dekt haar aansprakelijkheid tegenover anderen, niet de schade die zijzelf lijdt."], ["Via het Waarborgfonds Motorverkeer, dat alle schaden met buitenlandse voertuigen afhandelt.", "Het Waarborgfonds komt alleen in beeld bij onbekende of onverzekerde voertuigen; hier is de veroorzaker bekend en verzekerd."]]],
["Wat is het belangrijkste doel van het Europees schadeformulier na een aanrijding?", [["Samen met de tegenpartij de toedracht en de gegevens van beide partijen eenduidig vastleggen.", "Het formulier legt de feiten direct na het ongeval vast, wat de afwikkeling tussen verzekeraars versnelt en geschillen over de toedracht beperkt."], ["Op de plek van het ongeval bindend vaststellen welke bestuurder voor hoeveel procent aansprakelijk is.", "Het formulier legt feiten vast; de aansprakelijkheid wordt daarna door de verzekeraars beoordeeld. Ondertekening is geen schulderkenning."], ["De politie informeren, zodat een proces-verbaal kan worden opgemaakt.", "Het schadeformulier is voor de verzekeraars bestemd en vervangt geen aangifte of proces-verbaal."], ["De schade direct te laten uitbetalen door de verzekeraar van degene die het formulier als eerste invult.", "Wie het formulier invult, zegt niets over wie aansprakelijk is of welke verzekeraar betaalt."]]],
["Wanneer is een auto na een schade economisch total loss?", [["Als herstel meer kost dan de waarde vóór de schade minus de restwaarde.", "Herstel is dan economisch niet zinvol: het kost meer dan de waarde die door herstel wordt teruggewonnen. De verzekeraar vergoedt dan het verschil tussen waarde vóór de schade en restwaarde."], ["Als de auto zo zwaar beschadigd is dat technisch herstel niet meer mogelijk is.", "Dat is technisch total loss; bij economisch total loss is herstel wel mogelijk, maar te duur."], ["Als de auto ouder is dan tien jaar, ongeacht de omvang van de schade.", "De leeftijd van de auto bepaalt niet of er sprake is van total loss; het gaat om de verhouding tussen herstelkosten en waarde."], ["Als de herstelkosten hoger zijn dan het eigen risico op de cascoverzekering.", "Een schade boven het eigen risico wordt gewoon hersteld en vergoed; dat heeft met total loss niets te maken."]]],
["Wat houdt een aanschafwaarderegeling in een cascoverzekering voor een nieuwe auto in?", [["Bij total loss of diefstal kort na aanschaf wordt de aanschafwaarde vergoed, niet de dagwaarde.", "Een nieuwe auto verliest snel waarde. Deze regeling beschermt de eigenaar daartegen in de eerste jaren, met een afloop in de tijd volgens de polis."], ["De premie wordt vastgesteld op basis van de aanschafprijs en blijft gedurende de hele looptijd gelijk.", "De regeling gaat over de schadevergoeding bij total loss of diefstal, niet over de hoogte van de premie."], ["Bij elke reparatie worden uitsluitend nieuwe originele onderdelen gebruikt, zonder aftrek voor slijtage.", "Dat is een afspraak over herstel; een aanschafwaarderegeling ziet op de vergoeding als de auto verloren gaat."], ["De verzekeraar koopt de auto aan het einde van de looptijd terug tegen de oorspronkelijke aanschafwaarde.", "Een verzekeraar koopt geen auto's terug; de regeling bepaalt alleen de vergoeding bij een gedekte schade."]]],
["De familie Mulder trekt met haar auto een caravan naar Frankrijk. Onderweg raakt de caravan door een stuurfout een andere auto. Hoe is dit verzekerd?", [["Onder de WA van de auto; voor schade aan de caravan zelf is een eigen casco nodig.", "Een gekoppelde aanhanger of caravan wordt voor de aansprakelijkheid gezien als onderdeel van de combinatie met de auto. De eigen schade aan de caravan valt daarbuiten."], ["Zowel de schade aan de andere auto als aan de caravan valt onder de WA van de trekkende auto.", "De WA-verzekering dekt nooit eigen schade van de verzekerde, dus ook niet de schade aan de eigen caravan."], ["De aansprakelijkheid valt onder de AVP van de familie, omdat een caravan geen motorrijtuig is.", "Tijdens het trekken hoort de caravan bij het motorrijtuig; dan geldt de WA-verzekering van de auto en niet de AVP."], ["Niemand dekt de schade, omdat een caravan altijd een eigen verplichte WA-verzekering moet hebben.", "Voor een caravan achter een auto loopt de aansprakelijkheid via de WA van de trekkende auto; een aparte verplichte WA is er niet."]]],
["Ilse rijdt op een gewone elektrische fiets met trapondersteuning tot 25 km/u en veroorzaakt schade aan een geparkeerde auto. Welke verzekering dekt haar aansprakelijkheid in beginsel?", [["Haar AVP, omdat zo'n e-bike wettelijk als fiets geldt.", "Een fiets met trapondersteuning tot 25 km/u is geen motorrijtuig in de zin van de WAM. De aansprakelijkheid valt daarom onder de particuliere aansprakelijkheidsverzekering."], ["Een verplichte WA-verzekering voor de e-bike, omdat er een elektromotor aanwezig is.", "Die verplichting geldt voor de speed pedelec en andere motorrijtuigen, niet voor een gewone e-bike tot 25 km/u."], ["Haar fietsverzekering, omdat die naast diefstal ook altijd de aansprakelijkheid van de fietser dekt.", "Een fietsverzekering dekt doorgaans diefstal en schade aan de eigen fiets, niet de aansprakelijkheid tegenover anderen."], ["De WA-verzekering van de beschadigde auto, omdat die bij het voertuig hoort.", "De WA van de geparkeerde auto dekt de aansprakelijkheid van die bestuurder, niet schade die een ander aan de auto toebrengt."]]],
["Een klant heeft een auto van twaalf jaar oud met een lage dagwaarde en betaalt een hoge premie voor een allriskdekking. Welk advies past het best bij de zorgplicht?", [["Bespreken of een lichtere dekking, zoals WA of WA met beperkt casco, beter past bij de waarde van de auto.", "Bij een lage dagwaarde staat de premie voor allrisk vaak niet meer in verhouding tot de maximale uitkering. De adviseur weegt dat af met de klant en legt de keuze vast."], ["De allriskdekking ongewijzigd laten, omdat een zo breed mogelijke dekking voor de klant altijd het veiligst is.", "De breedste dekking is niet automatisch passend; de adviseur moet ook nagaan of premie en mogelijke uitkering in verhouding staan."], ["De autoverzekering helemaal laten vervallen, omdat de auto toch weinig waard is.", "De WA-verzekering is wettelijk verplicht zolang de auto op de openbare weg komt; laten vervallen is geen optie."], ["Een hogere verzekerde waarde opgeven dan de dagwaarde, zodat de klant bij total loss meer ontvangt.", "Bij een schadeverzekering wordt de werkelijke schade vergoed; een te hoge opgave levert geen hogere uitkering op en kan als misleiding worden gezien."]]],
["Waarom is de WOZ-waarde geen goede basis voor het verzekerde bedrag van een woonhuisverzekering?", [["Het is een marktwaarde inclusief grond, terwijl het om de herbouwkosten van het gebouw gaat.", "Grond kan niet afbranden, en marktwaarde zegt weinig over bouwkosten. Daarom wordt het verzekerde bedrag gebaseerd op de herbouwwaarde."], ["De WOZ-waarde wordt maar eens in de vijf jaar vastgesteld en is daardoor altijd veel te laag.", "De WOZ-waarde wordt jaarlijks bepaald; het probleem is niet de frequentie maar het feit dat het een andere waarde meet."], ["De WOZ-waarde mag alleen door de gemeente worden gebruikt en is voor verzekeraars niet beschikbaar.", "WOZ-waarden zijn in Nederland in beginsel openbaar in te zien; de reden is inhoudelijk, niet de beschikbaarheid."], ["De WOZ-waarde houdt al rekening met onderverzekering en zou daardoor dubbel tellen in de polis.", "De WOZ-waarde is een waardering voor de belastingheffing en houdt geen rekening met verzekeringsbegrippen zoals onderverzekering."]]],
["Een klant sluit een hypotheek voor de aankoop van een woning. Waarom eist de geldverstrekker vrijwel altijd een opstalverzekering?", [["Omdat de woning het onderpand is en de waarde daarvan bij schade beschermd moet zijn.", "Gaat de woning verloren zonder verzekering, dan verliest de geldverstrekker zijn zekerheid. Daarom stelt hij een woonhuisverzekering als voorwaarde."], ["Omdat de opstalverzekering bij overlijden van de klant de hypotheekschuld aflost.", "Aflossing bij overlijden is de functie van een overlijdensrisicoverzekering; een opstalverzekering dekt schade aan het gebouw."], ["Omdat een opstalverzekering wettelijk verplicht is voor iedere eigenaar van een woning in Nederland.", "Er is geen wettelijke plicht; de eis komt voort uit de voorwaarden van de geldverstrekker."], ["Omdat de geldverstrekker zo provisie kan ontvangen op een verzekering die bij de lening hoort.", "De eis dient de zekerheid van het onderpand; een eventuele beloning is niet de reden voor de voorwaarde."]]],
["Een woning in Groningen heeft scheuren door aardbevingen als gevolg van gaswinning. Waar kan de eigenaar in de eerste plaats terecht?", [["Bij het Instituut Mijnbouwschade Groningen.", "Schade door mijnbouw in Groningen valt onder een publieke regeling die door dit instituut wordt uitgevoerd. Een gewone woonhuispolis sluit aardbevingsschade doorgaans uit."], ["Bij de eigen woonhuisverzekeraar, omdat aardbevingsschade standaard onder de allriskdekking valt.", "Aardbeving is in Nederlandse woonhuispolissen doorgaans uitgesloten; de mijnbouwschade wordt via een aparte publieke route afgehandeld."], ["Bij het Kifid, omdat dit geschil over schadevergoeding met een financiële onderneming gaat.", "Het Kifid behandelt klachten over financiële dienstverleners; de afhandeling van mijnbouwschade is daar niet ondergebracht."], ["Bij de Nederlandse Herverzekeringsmaatschappij voor Terrorismeschaden.", "De NHT herverzekert terrorismeschade en heeft geen rol bij schade door gaswinning."]]],
["Bij de woning van meneer Vos is de fundering in de loop van jaren verzakt door een dalende grondwaterstand, waardoor scheuren in de muren zijn ontstaan. Is dit doorgaans gedekt op de woonhuisverzekering?", [["Nee, de schade is geleidelijk ontstaan en niet door een plotselinge gebeurtenis.", "Woonhuispolissen dekken plotselinge en onvoorziene schade. Een verzakking die over jaren ontstaat, is geleidelijk en valt doorgaans buiten de dekking."], ["Ja, omdat een woonhuisverzekering op allriskbasis alle schade aan de fundering dekt.", "Ook een allriskdekking vereist een plotselinge, onvoorziene gebeurtenis; geleidelijke verzakking valt daar niet onder."], ["Ja, mits meneer Vos binnen twee maanden na het ontdekken van de scheuren een melding doet.", "Een tijdige melding verandert niets aan het karakter van de schade; geleidelijke schade blijft buiten de dekking."], ["Nee, maar het Waarborgfonds vergoedt funderingsschade als de verzekeraar weigert.", "Het Waarborgfonds Motorverkeer is er voor verkeersslachtoffers, niet voor funderingsschade aan woningen."]]],
["Welke waterschade is in een woonhuis- of inboedelpolis doorgaans NIET gedekt?", [["Schade door water dat de kelder binnenkomt door een stijgende grondwaterstand.", "Grondwater stijgt geleidelijk en is een algemeen gebiedsrisico; polissen sluiten deze schade doorgaans uit."], ["Schade door water dat plotseling uit een gesprongen waterleiding in de badkamer stroomt.", "Water dat plotseling uit een leiding stroomt door een defect is een klassieke gedekte gebeurtenis."], ["Schade door regen die na een stormschade door het beschadigde dak naar binnen komt.", "Dit is gevolgschade van een gedekte storm, en wordt dan in de regel ook vergoed."], ["Schade door water uit een wasmachine waarvan de aanvoerslang plotseling losschiet.", "Water uit een aangesloten toestel dat plotseling vrijkomt, valt doorgaans onder de dekking van de polis."]]],
["Een woningeigenaar laat zonnepanelen vast op zijn dak monteren. Wat is voor de verzekering het belangrijkste aandachtspunt?", [["Nagaan of de panelen als deel van het woonhuis zijn meeverzekerd en of het verzekerde bedrag nog toereikend is.", "Vast gemonteerde panelen horen doorgaans bij het gebouw. De waardestijging moet wel in de herbouwwaarde worden meegenomen, anders dreigt onderverzekering."], ["De panelen moeten altijd onder de inboedelverzekering worden gebracht, omdat zij elektrische apparatuur zijn.", "Vast aan de woning bevestigde voorzieningen horen in de regel bij het woonhuis, niet bij de inboedel."], ["De panelen moeten verplicht apart worden verzekerd via een energieleverancier.", "Een aparte verzekering kan, maar is niet verplicht; meestal vallen de panelen onder de woonhuisverzekering."], ["De verzekering hoeft niet te worden aangepast, omdat herbouwwaarden jaarlijks automatisch alle verbouwingen meenemen.", "Indexering volgt prijsontwikkelingen, niet wijzigingen aan de woning zelf; een uitbreiding moet de klant melden of laten meenemen."]]],
["Welk van de volgende bezittingen valt doorgaans NIET onder de dekking van een inboedelverzekering?", [["De personenauto van het gezin.", "Motorrijtuigen zijn uitgezonderd van het begrip inboedel; die worden verzekerd via een autoverzekering met WA en eventueel casco."], ["De meubels en vloerbedekking in de woonkamer.", "Losse meubels en vloerbedekking zijn klassieke inboedel van een particulier huishouden."], ["De kleding en schoenen van de gezinsleden.", "Kleding hoort tot de roerende zaken voor particulier gebruik en valt dus onder de inboedel."], ["Een laptop die het gezin thuis voor privédoeleinden gebruikt.", "Audiovisuele en computerapparatuur voor privégebruik valt onder inboedel, vaak met een eigen maximum."]]],
["Een inboedelpolis vergoedt op basis van nieuwwaarde. Bij welke zaken geldt in veel polissen toch een vergoeding op basis van dagwaarde?", [["Bij zaken met een dagwaarde onder een vast deel van de nieuwwaarde, vaak 40%.", "Bij sterk verouderde zaken zou nieuwwaarde te veel verrijking opleveren. Polissen beperken daarom de vergoeding tot dagwaarde onder een vaste grens."], ["Bij alle zaken die korter dan een jaar geleden zijn gekocht.", "Bij recent gekochte zaken liggen dagwaarde en nieuwwaarde dicht bij elkaar; daar is nieuwwaardevergoeding juist het minst bezwaarlijk."], ["Bij zaken die door brand verloren gaan, omdat brand een groot risico is.", "De oorzaak van de schade bepaalt niet of op dagwaarde of nieuwwaarde wordt vergoed; het gaat om de staat van de zaak."], ["Bij zaken die de verzekerde met contant geld heeft betaald in plaats van per bank.", "De manier van betalen bij aankoop heeft geen invloed op de vergoedingsbasis."]]],
["Na een inbraak blijkt dat de achterdeur niet was voorzien van het slot dat de inboedelpolis voorschrijft. Wat kan hiervan het gevolg zijn?", [["De verzekeraar kan de dekking voor diefstal beperken of weigeren, afhankelijk van wat de polis bepaalt.", "Polissen stellen vaak eisen aan inbraakpreventie. Wordt daar niet aan voldaan, dan kan de diefstaldekking volgens de voorwaarden vervallen of beperkt zijn."], ["Geen gevolg, omdat eisen aan sloten alleen gelden voor bedrijfspanden en niet voor particuliere woningen.", "Ook particuliere inboedelpolissen stellen regelmatig eisen aan sloten of een keurmerk voor inbraakpreventie."], ["De verzekeraar moet volledig uitkeren, maar mag de premie voor het volgende jaar verdubbelen.", "De polisvoorwaarden bepalen het gevolg voor de dekking; een vaste premieverdubbeling als sanctie is niet de regel."], ["De verzekeraar mag alle andere polissen van de klant direct met terugwerkende kracht beëindigen.", "Niet voldoen aan een preventie-eis is geen fraude; het rechtvaardigt geen beëindiging met terugwerkende kracht van andere polissen."]]],
["De familie Peters koopt een woning. De koopakte bepaalt dat het risico overgaat bij de levering bij de notaris. Vanaf wanneer moet de familie de woning in ieder geval zelf verzekeren?", [["Vanaf de levering bij de notaris.", "Vanaf dat moment zijn zij eigenaar en dragen zij het risico. De opstalverzekering moet dan zijn ingegaan, wat ook de geldverstrekker eist."], ["Vanaf het moment dat de voorlopige koopovereenkomst is getekend.", "Na het tekenen is de koop gesloten, maar volgens deze afspraak blijft het risico tot de levering bij de verkoper."], ["Vanaf de dag waarop de familie in de woning gaat wonen, ook als dat maanden na de levering is.", "Het risico ligt vanaf de levering al bij de koper; wachten tot de verhuizing laat een periode onverzekerd."], ["Vanaf het moment dat de hypotheekverstrekker het hypotheekaanbod heeft uitgebracht.", "Het aanbod van de geldverstrekker heeft geen invloed op de vraag wie het risico van de woning draagt."]]],
["Sem is 17 jaar en woont bij zijn ouders. Hij beschadigt bij het skateboarden de auto van een buurman. Wie is in beginsel aansprakelijk?", [["Sem zelf; de bijzondere ouderaansprakelijkheid geldt niet meer vanaf 16 jaar.", "Vanaf 16 jaar is een jongere zelf aansprakelijk voor zijn onrechtmatige daad. Ouders zijn dan alleen aansprakelijk bij een eigen fout; via een gezins-AVP is Sem meestal wel meeverzekerd."], ["Zijn ouders, op grond van risicoaansprakelijkheid voor kinderen tot 18 jaar.", "De bijzondere aansprakelijkheid van ouders loopt niet tot 18 jaar; voor kinderen tot 14 is zij risicoaansprakelijkheid, voor 14 en 15 jaar schuldaansprakelijkheid."], ["Niemand, omdat een minderjarige niet aansprakelijk kan zijn voor schade aan zaken.", "Minderjarigheid sluit aansprakelijkheid alleen uit bij kinderen onder de 14 jaar; een jongere van 17 is zelf aansprakelijk."], ["De buurman zelf, omdat hij zijn auto op een plek parkeerde waar kinderen spelen.", "Waar een auto geparkeerd staat, maakt de schade niet tot een risico van de buurman; Sem heeft de schade veroorzaakt."]]],
["Van het dak van de woning van mevrouw Dekker valt bij matige wind een losliggende dakpan op een geparkeerde auto. Welke aansprakelijkheid speelt hier?", [["Risicoaansprakelijkheid van de bezitter van de gebrekkige opstal, ook zonder schuld.", "Een opstal die niet voldoet aan de eisen die men daaraan mag stellen, levert gevaar op voor anderen. De bezitter is dan aansprakelijk; via de AVP of de woonhuispolis is dit vaak gedekt."], ["Geen aansprakelijkheid, omdat windschade altijd als overmacht geldt en niemand iets te verwijten valt.", "Bij matige wind hoort een dakpan niet los te raken; het gebrek aan de opstal maakt de bezitter aansprakelijk."], ["Alleen aansprakelijkheid als de eigenaar van de auto kan bewijzen dat mevrouw Dekker van het gebrek wist.", "Bij deze risicoaansprakelijkheid hoeft de benadeelde geen schuld of wetenschap van de bezitter te bewijzen."], ["Aansprakelijkheid van de gemeente, omdat de auto op de openbare weg stond geparkeerd.", "De plek waar de auto stond, maakt de gemeente niet aansprakelijk voor een gebrek aan een particuliere woning."]]],
["Een zoon beschadigt per ongeluk de laptop van zijn vader. Beiden zijn verzekerd op dezelfde gezins-AVP. Wat geldt doorgaans?", [["Geen dekking, omdat zaakschade tussen verzekerden op dezelfde polis is uitgesloten.", "Een AVP dekt aansprakelijkheid tegenover derden. Zaakschade tussen medeverzekerden onderling is uitgesloten om onderlinge claims binnen het gezin te voorkomen."], ["Volledige dekking, omdat de vader als benadeelde een andere persoon is dan de zoon als veroorzaker.", "Dat de vader een andere persoon is, maakt hem op dezelfde gezinspolis nog geen derde voor zaakschade."], ["Dekking op dagwaarde, omdat de AVP bij schade binnen het gezin altijd de dagwaarde vergoedt.", "Een dagwaardevergoeding binnen het gezin is geen standaardregeling; de schade is doorgaans helemaal uitgesloten."], ["Dekking, mits de zoon ouder is dan 14 jaar en dus zelf aansprakelijk is.", "De leeftijd van de zoon verandert niets aan de uitsluiting van zaakschade tussen verzekerden onderling."]]],
["Een verzekerde veroorzaakt als fietser een ongeval waarbij een voetganger letsel oploopt. De voetganger vraagt ook smartengeld. Valt dat onder de AVP?", [["Ja, de AVP dekt bij aansprakelijkheid voor letsel ook immateriële schade zoals smartengeld.", "Personenschade omvat zowel materiële schade, zoals verlies van inkomen, als immateriële schade. Beide vallen binnen de dekking voor aansprakelijkheid."], ["Nee, een AVP vergoedt uitsluitend materiële schade, zoals medische kosten en schade aan kleding.", "Ook immateriële schade waarvoor de verzekerde aansprakelijk is, valt onder de dekking voor personenschade."], ["Nee, smartengeld wordt altijd door de zorgverzekeraar van het slachtoffer betaald.", "Een zorgverzekeraar vergoedt zorgkosten, geen smartengeld; dat moet de aansprakelijke partij betalen."], ["Alleen als de rechter het smartengeld heeft vastgesteld, en dan tot de helft van het bedrag.", "Smartengeld kan ook in een schikking worden vastgesteld, en de AVP dekt het binnen de verzekerde som volledig."]]],
["Wat houdt affectieschade in het Nederlandse aansprakelijkheidsrecht in?", [["Een vergoeding voor het leed van naasten bij ernstig blijvend letsel of overlijden van een dierbare.", "Sinds de invoering van de wet affectieschade kunnen bepaalde naasten zelf een vergoeding krijgen voor hun verdriet; de aansprakelijke en diens verzekeraar betalen."], ["De vergoeding van de emotionele waarde van een beschadigde zaak, zoals een erfstuk.", "Affectieschade gaat over het leed van naasten bij ernstig letsel of overlijden, niet over gehechtheid aan een voorwerp."], ["Een vergoeding die het slachtoffer zelf krijgt voor pijn en verdriet na een ongeval.", "Dat is smartengeld voor het slachtoffer zelf; affectieschade is een eigen vergoeding voor de naasten."], ["Schade die ontstaat doordat iemand een schok krijgt bij het waarnemen van een ongeval met een vreemde.", "Dat lijkt op shockschade, waarvoor andere eisen gelden; affectieschade is gekoppeld aan een nauwe band met het slachtoffer."]]],
["Een voetganger steekt onverwacht over zonder op te letten en wordt geraakt door een fietser die zelf ook te hard reed. Wat betekent de fout van de voetganger voor zijn schadevergoeding?", [["Zijn vergoeding kan worden verminderd naar de mate van zijn eigen schuld.", "Als de benadeelde zelf heeft bijgedragen aan de schade, wordt de vergoeding verdeeld naar de mate waarin ieders gedrag tot de schade heeft bijgedragen, eventueel bijgesteld op billijkheid."], ["Geen gevolg, omdat een voetganger bij een aanrijding altijd volledig wordt vergoed.", "De bijzondere bescherming van voetgangers geldt tegenover motorrijtuigen; tegenover een fietser geldt de gewone regeling van eigen schuld."], ["Hij krijgt niets vergoed, omdat hij zelf in strijd met de verkeersregels handelde.", "Eigen schuld leidt tot een verdeling van de schade, niet automatisch tot verlies van elke vergoeding."], ["De fietser en de voetganger dragen ieder altijd precies de helft van alle schade.", "Er is geen vaste verdeling van de helft; de verdeling hangt af van de concrete bijdrage van ieder aan het ongeval."]]],
["Wanneer is een gedraging volgens het Burgerlijk Wetboek onrechtmatig?", [["Bij inbreuk op een recht, strijd met een wettelijke plicht of strijd met ongeschreven maatschappelijke zorgvuldigheid.", "Dit zijn de drie categorieën van onrechtmatigheid. Daarnaast moet onder meer aan toerekening, schade en causaal verband zijn voldaan voor aansprakelijkheid."], ["Uitsluitend bij strijd met een wettelijke bepaling die met straf is bedreigd, zoals een bepaling uit het Wetboek van Strafrecht.", "Onrechtmatigheid is veel ruimer dan strafbaar gedrag; ook onzorgvuldig handelen kan onrechtmatig zijn."], ["Alleen als de dader het opzet had om de benadeelde schade toe te brengen of dat bewust heeft aanvaard.", "Opzet is geen vereiste; ook onvoorzichtigheid kan een onrechtmatige daad opleveren."], ["Alleen als er tussen dader en benadeelde een overeenkomst bestond die door de dader is geschonden.", "Schending van een overeenkomst is wanprestatie; onrechtmatige daad juist veronderstelt geen contract tussen partijen."]]],
["Een jong stel met een beperkt budget wil kiezen welke particuliere verzekering zij als eerste afsluiten. Waarom wordt de AVP vaak als een van de belangrijkste gezien?", [["Omdat de schade waarvoor men aansprakelijk kan zijn, zoals letselschade, onbeperkt hoog kan oplopen.", "Een aansprakelijkheidsclaim kan iemands financiële positie voor jaren ontwrichten. Verzekeren past juist bij een kleine kans op een zeer grote schade, en de premie is relatief laag."], ["Omdat een AVP wettelijk verplicht is voor iedereen die in Nederland woont.", "Een AVP is niet wettelijk verplicht; alleen de WA-verzekering voor motorrijtuigen kent een wettelijke plicht."], ["Omdat de AVP ook schade aan de eigen spullen vergoedt, zodat een inboedelverzekering overbodig wordt.", "Een AVP dekt schade aan anderen, niet aan eigen zaken; daarvoor blijft een inboedelverzekering nodig."], ["Omdat een AVP het vaakst uitkeert van alle particuliere verzekeringen.", "De AVP keert niet het vaakst uit; de waarde zit juist in de bescherming tegen zeldzame maar zeer grote claims."]]],
["Welke schade valt in een AVP in de regel NIET onder de dekking?", [["Zuivere vermogensschade die niet voortvloeit uit schade aan een persoon of zaak.", "Een AVP dekt aansprakelijkheid voor schade aan personen en zaken, met de gevolgschade daarvan. Een puur financieel nadeel zonder letsel of zaakschade valt doorgaans buiten de dekking."], ["De gederfde inkomsten van iemand die door de verzekerde letsel heeft opgelopen.", "Inkomensverlies door letsel is gevolgschade van personenschade en valt daarom wel onder de dekking."], ["De kosten van herstel van een fiets die de verzekerde per ongeluk heeft omgereden.", "Dit is zaakschade aan een derde en valt binnen de dekking, tenzij de fiets onder opzicht van de verzekerde was."], ["De medische kosten van een voorbijganger die door de hond van de verzekerde is gebeten.", "Schade door een eigen huisdier aan een derde is een gebruikelijke gedekte aansprakelijkheid binnen de AVP."]]],
["Wat is het verschil tussen een rechtsbijstandverzekering in natura en een kostenverzekering?", [["Bij natura helpt de verzekeraar zelf met eigen juristen; bij een kostenverzekering vergoedt hij een externe hulpverlener.", "Bij natura is de hulp zelf de prestatie. Bij een kostenverzekering kiest de verzekerde een hulpverlener en vergoedt de verzekeraar diens kosten binnen de polis."], ["Bij natura krijgt de verzekerde een vast bedrag uitgekeerd; bij een kostenverzekering worden alle kosten onbeperkt vergoed.", "Natura betekent geen vast bedrag maar hulp in de vorm van dienstverlening; en ook een kostenverzekering kent maxima."], ["Bij natura geldt geen wachttijd; bij een kostenverzekering geldt altijd een wachttijd van een jaar.", "Wachttijden hangen af van de polis en het soort geschil, niet van de vorm waarin de hulp wordt verleend."], ["Er is geen verschil; beide termen worden door verzekeraars door elkaar gebruikt voor hetzelfde product.", "Het zijn verschillende vormen van dekking, met elk andere gevolgen voor wie de hulp feitelijk verleent."]]],
["Waarom hanteren rechtsbijstandverzekeringen vaak een minimumbelang voordat zij hulp verlenen?", [["Om te voorkomen dat de kosten van hulp niet opwegen tegen het belang van het geschil.", "Bij een geschil over een klein bedrag zijn de kosten van juridische hulp vaak hoger dan het belang. Een drempel houdt de premie betaalbaar."], ["Om te zorgen dat alleen geschillen met een overheidsinstantie onder de dekking vallen.", "Een minimumbelang zegt iets over de hoogte van het geschil, niet over de tegenpartij."], ["Om de verzekerde te dwingen kleine geschillen altijd aan het Kifid voor te leggen.", "Kifid behandelt alleen klachten over financiële dienstverleners, niet elk klein geschil van een verzekerde."], ["Omdat de wet bepaalt dat geschillen onder een bepaald bedrag niet bij de rechter kunnen worden voorgelegd.", "Ook kleine geschillen kunnen bij de kantonrechter worden voorgelegd; de drempel is een polisafspraak."]]],
["Een verzekerde wil in een procedure bij de kantonrechter, waar geen advocaat verplicht is, zelf een advocaat kiezen. De rechtsbijstandverzekeraar wil de zaak door een eigen jurist laten doen. Wat geldt volgens Europese rechtspraak?", [["De vrije keuze geldt in elke procedure, ook als een advocaat niet verplicht is.", "Het Hof van Justitie van de EU heeft geoordeeld dat de vrije advocaatkeuze niet beperkt mag worden tot procedures met verplichte procesvertegenwoordiging. Een polis mag wel een redelijk maximum aan externe kosten stellen."], ["De vrije keuze geldt alleen in procedures waarin een advocaat wettelijk verplicht is.", "Die beperking is door het Hof van Justitie juist afgewezen; ook bij de kantonrechter bestaat de vrije keuze."], ["De verzekeraar mag altijd zelf bepalen wie de zaak behandelt, omdat hij de kosten betaalt.", "Het recht op vrije keuze beschermt de verzekerde tegen een verzekeraar die de behandelaar eenzijdig bepaalt."], ["De verzekerde mag alleen kiezen als hij de kosten van de gekozen advocaat zelf betaalt.", "Bij vrije keuze vergoedt de verzekeraar de kosten binnen de voorwaarden van de polis; de keuze is niet afhankelijk van zelf betalen."]]],
["Waarom laten veel verzekeraars die ook andere schadeverzekeringen aanbieden de rechtsbijstand uitvoeren door een aparte entiteit, zoals een stichting?", [["Om belangenconflicten te voorkomen, bijvoorbeeld bij een geschil met een andere klant van die verzekeraar.", "Europese regels eisen dat de behandeling van rechtsbijstandzaken is gescheiden van andere branches of dat een vrije keuze van de rechtshulpverlener wordt geboden. Een aparte uitvoerder is een gangbare oplossing."], ["Om de premie voor rechtsbijstand fiscaal aftrekbaar te maken voor de verzekerde.", "De rechtsvorm van de uitvoerder heeft geen invloed op de fiscale behandeling van de premie voor een particulier."], ["Omdat juristen alleen in dienst mogen zijn van een stichting en niet van een verzekeraar.", "Er is geen regel dat juristen alleen voor stichtingen mogen werken; het gaat om het scheiden van belangen."], ["Omdat juristen volgens de beroepsregels alleen in dienst mogen zijn van een stichting en niet van een verzekeraar.", "Ook over rechtsbijstand kan een consument bij Kifid klagen; de aparte uitvoerder dient de onafhankelijkheid."]]],
["Een autoverzekering bevat een dekking voor verhaalsrechtsbijstand. Wat houdt die in?", [["Hulp bij het verhalen van de eigen schade op de aansprakelijke tegenpartij.", "Verhaalsrechtsbijstand helpt de verzekerde zijn schade te claimen bij degene die aansprakelijk is. Het is geen verweer tegen claims van anderen."], ["Hulp bij het verweer tegen een claim van een tegenpartij die de verzekerde aansprakelijk stelt.", "Verweer tegen een claim valt onder de WA-dekking, waarbij de verzekeraar het verweer voert; verhaalsbijstand werkt de andere kant op."], ["Juridische hulp bij alle geschillen van de verzekerde, ook buiten het verkeer.", "Verhaalsrechtsbijstand bij een autopolis is beperkt tot verhaal van schade uit verkeersongevallen met het verzekerde voertuig."], ["Een vergoeding van boetes die de verzekerde na een verkeersovertreding moet betalen.", "Boetes zijn nooit verzekerbaar; verhaalsrechtsbijstand gaat over het verhalen van schade."]]],
["Meneer Yilmaz krijgt een conflict met zijn werkgever over zijn ontslag. Welk onderdeel van een modulaire rechtsbijstandverzekering is hiervoor nodig?", [["De module voor werk en inkomen.", "Arbeidsconflicten vallen onder de module die ziet op werk, ontslag en inkomen. Zonder die module is er voor dit geschil geen dekking."], ["De module voor consument en wonen, omdat het om een geschil van een particulier gaat.", "De module consument en wonen ziet op geschillen over aankopen en de woning, niet op de arbeidsverhouding."], ["De module voor verkeer, omdat meneer Yilmaz met de auto naar zijn werk reist.", "De manier van reizen naar het werk maakt een ontslagconflict niet tot een verkeerszaak."], ["Geen module, omdat arbeidsconflicten alleen via een vakbond kunnen worden behandeld.", "Een vakbond kan helpen, maar arbeidsconflicten zijn wel degelijk verzekerbaar via rechtsbijstand."]]],
["Een verzekerde wordt verdacht van een opzetdelict. Hoe gaan veel rechtsbijstandpolissen hiermee om?", [["Vooraf geen dekking, maar na vrijspraak worden de kosten alsnog vergoed.", "Verzekeraars willen geen hulp bieden bij opzettelijk strafbaar handelen. Blijkt de verdenking onterecht, dan worden de kosten na vrijspraak alsnog vergoed."], ["Er is altijd volledige dekking, omdat iedere verdachte recht heeft op een advocaat.", "Het recht op een advocaat betekent niet dat een rechtsbijstandverzekeraar bij elk opzetdelict de kosten draagt."], ["Er is alleen dekking als de verzekerde schuld bekent, zodat de zaak snel kan worden afgedaan.", "Het afhankelijk maken van dekking van een bekentenis zou in strijd zijn met de rechten van een verdachte en is geen gangbare regeling."], ["De verzekeraar betaalt een eventuele boete, maar niet de kosten van de advocaat.", "Boetes zijn niet verzekerbaar; de regeling ziet juist op de kosten van rechtsbijstand."]]],
["Een klant met een doorlopende reisverzekering wil een wereldreis van acht maanden maken. Wat is het belangrijkste aandachtspunt?", [["Er geldt meestal een maximale aaneengesloten reisduur; voor deze reis is mogelijk een aparte polis nodig.", "Doorlopende polissen dekken meestal reizen tot een bepaald aantal dagen achter elkaar. Bij een langere reis vervalt de dekking na die termijn of voor de hele reis, afhankelijk van de voorwaarden."], ["Er is geen aandachtspunt, omdat een doorlopende reisverzekering het hele jaar door onbeperkt dekking biedt.", "Doorlopend betekent dat de polis geldt voor alle reizen in de looptijd, niet dat elke reisduur is gedekt."], ["De klant moet de reis melden bij de zorgverzekeraar, omdat de reisverzekering bij langere reizen vervalt.", "De zorgverzekering is van belang voor medische kosten, maar het punt hier is de maximale reisduur van de reisverzekering zelf."], ["De klant moet zijn inboedelverzekering opzeggen, omdat hij langer dan een half jaar niet thuis is.", "Leegstand kan relevant zijn voor de inboedelpolis, maar opzeggen is niet nodig en de vraag gaat over de reisdekking."]]],
["Wat biedt de Europese zorgpas (EHIC) een Nederlandse verzekerde tijdens een tijdelijk verblijf in een ander EU-land?", [["Noodzakelijke zorg onder dezelfde voorwaarden als voor inwoners van dat land.", "De zorgpas geeft recht op noodzakelijke zorg tegen de lokale voorwaarden en tarieven. Kosten die daar voor eigen rekening komen of hoger zijn, worden niet gedekt; daarvoor dient een reisverzekering."], ["Volledige vergoeding van alle medische kosten, inclusief repatriëring naar Nederland.", "Repatriëring valt niet onder de zorgpas; daarvoor is een reisverzekering met hulpverlening nodig."], ["Dekking voor diefstal van bagage en annulering van de reis.", "De zorgpas gaat uitsluitend over medische zorg, niet over bagage of annulering."], ["Een vervanging van de zorgverzekering, zodat die tijdens de reis kan worden stopgezet.", "De zorgpas werkt juist op basis van de Nederlandse zorgverzekering; die moet blijven doorlopen."]]],
["Een verzekerde breekt tijdens een vakantie in Spanje zijn been en moet met medische begeleiding terug naar Nederland. Welke rol speelt de alarmcentrale van de reisverzekeraar?", [["Zij regelt de hulp en het medisch vervoer naar huis, in overleg met de artsen.", "De alarmcentrale regelt de praktische hulp en het medische vervoer en beoordeelt met artsen wat nodig is. De kosten vallen onder de hulpverleningsdekking van de reisverzekering."], ["Zij stelt de aansprakelijkheid van de verzekerde vast voor het ongeval.", "Aansprakelijkheid is hier niet aan de orde; de alarmcentrale verleent praktische en medische hulp."], ["Zij vergoedt uitsluitend achteraf de kosten die de verzekerde zelf heeft voorgeschoten.", "De alarmcentrale regelt de hulp juist actief tijdens de reis, en betaalt kosten vaak rechtstreeks."], ["Zij behandelt klachten over de afhandeling van de schade, als onafhankelijke instantie.", "Klachten gaan naar de verzekeraar zelf en daarna naar Kifid; de alarmcentrale is onderdeel van de hulpverlening."]]],
["Een klant gaat op wintersport en wil ook gaan skiën buiten de pistes. Waar moet de adviseur op letten?", [["Of wintersport is meeverzekerd en of skiën buiten de piste niet is uitgesloten.", "Veel reispolissen vragen een aanvullende dekking voor wintersport en sluiten bepaalde risicovolle activiteiten uit of beperken die. De adviseur moet dit vooraf met de klant nagaan."], ["Nergens op, omdat een reisverzekering alle sporten dekt die op de vakantiebestemming gangbaar zijn.", "Een algemene dekking voor alle sporten is ongebruikelijk; risicovolle activiteiten zijn vaak uitgesloten of alleen tegen extra premie gedekt."], ["Alleen of de zorgverzekering van de klant ook wintersportbagage vergoedt.", "Een zorgverzekering dekt geen bagage; wintersportuitrusting valt onder de reisverzekering."], ["Of de klant een cursus heeft gevolgd, omdat de reisverzekering anders nooit medische kosten vergoedt.", "Medische kosten worden niet afhankelijk gesteld van het volgen van een cursus; het gaat om de reikwijdte van de dekking."]]],
["Tijdens een stedentrip wordt een fototoestel gestolen uit de kofferbak van een geparkeerde auto die de hele dag onbeheerd stond. Wat is een gebruikelijk punt van discussie bij de reisverzekering?", [["Veel polissen sluiten diefstal van kostbaarheden uit een onbeheerde auto uit of beperken die.", "Reisverzekeringen stellen eisen aan de zorg voor bagage. Kostbaarheden die lang in een onbeheerde auto achterblijven, zijn vaak niet of beperkt gedekt."], ["Er is nooit discussie, omdat diefstal op reis altijd volledig op nieuwwaarde wordt vergoed.", "Bagage wordt meestal op dagwaarde vergoed met maxima, en de zorgvuldigheid van de verzekerde speelt een rol."], ["De verzekeraar vergoedt het fototoestel alleen als de auto een huurauto was.", "Of het een eigen auto of huurauto is, is niet het gebruikelijke criterium; het gaat om de onbeheerde situatie."], ["De schade valt altijd onder de cascoverzekering van de auto in plaats van onder de reisverzekering.", "Een cascoverzekering dekt de auto zelf, niet de spullen die erin achterblijven."]]],
["Een reisverzekering bevat een rubriek ongevallen met een vast bedrag bij overlijden of blijvende invaliditeit. Wat is dit voor soort dekking?", [["Een sommenverzekering: er wordt een vooraf vastgesteld bedrag uitgekeerd.", "Bij een ongevallendekking is de uitkering een vast bedrag of een percentage daarvan bij invaliditeit. Het indemniteitsbeginsel speelt hier geen rol."], ["Een schadeverzekering: de werkelijke inkomensschade na het ongeval wordt vergoed.", "De rubriek keert vaste bedragen uit en is daardoor geen schadeverzekering in de zin van BW 7."], ["Een aansprakelijkheidsverzekering: de uitkering gaat naar degene die het ongeval veroorzaakte.", "De ongevallenrubriek keert uit aan de verzekerde of zijn nabestaanden, niet aan een veroorzaker."], ["Een zorgverzekering: de uitkering is bedoeld voor medische kosten in het buitenland.", "Medische kosten vallen onder een aparte rubriek; de ongevallenrubriek keert een vast bedrag uit."]]],
["Een reisorganisatie gaat failliet vlak voordat een gezin op pakketreis zou vertrekken. Welke regeling kan het gezin beschermen als de organisatie is aangesloten?", [["De Stichting Garantiefonds Reisgelden, bij insolventie van de reisorganisatie.", "Bij een pakketreis is de reiziger beschermd tegen insolventie van de organisator. Voor aangesloten organisaties regelt het Garantiefonds terugbetaling of voortzetting van de reis."], ["Het Calamiteitenfonds Reizen, dat vergoeding biedt als een reisorganisatie failliet gaat.", "Het Calamiteitenfonds ziet op calamiteiten op de bestemming, zoals natuurrampen, niet op faillissement van de organisatie."], ["De annuleringsverzekering van het gezin, die faillissement van de reisorganisatie altijd dekt.", "Annuleringsverzekeringen dekken persoonlijke annuleringsredenen; faillissement van de organisator is daar meestal niet bij."], ["Het Waarborgfonds Motorverkeer, als de reis met een touringcar zou plaatsvinden.", "Het Waarborgfonds betreft verkeersschade door onverzekerde of onbekende voertuigen, niet faillissement van een reisorganisatie."]]],
["Een klant wil via zijn adviseur een uitvaartverzekering afsluiten. Mag de adviseur hiervoor provisie van de verzekeraar ontvangen?", [["Nee, voor uitvaartverzekeringen geldt het provisieverbod.", "Het provisieverbod geldt onder meer voor uitvaartverzekeringen. De klant betaalt de adviseur rechtstreeks, bijvoorbeeld via een vast tarief of uurtarief."], ["Ja, uitvaartverzekeringen zijn schadeverzekeringen waarvoor provisie zonder meer is toegestaan.", "Anders dan bij bijvoorbeeld inboedel- of autoverzekeringen valt de uitvaartverzekering juist onder het provisieverbod."], ["Ja, mits de adviseur de hoogte van de provisie vooraf aan de klant meldt.", "Transparantie maakt provisie niet toelaatbaar bij producten waarvoor het provisieverbod geldt."], ["Alleen bij een naturaverzekering, omdat de klant daar geen geldbedrag ontvangt.", "Het verbod maakt voor uitvaartverzekeringen geen onderscheid tussen natura en kapitaal."]]],
["Wat is voor nabestaanden een kenmerkend voordeel van een kapitaaluitvaartverzekering ten opzichte van een naturaverzekering?", [["Zij kunnen het uitgekeerde bedrag vrij besteden en zelf een uitvaartondernemer kiezen.", "Bij een kapitaalverzekering ontvangt de begunstigde geld. Dat geeft vrijheid in de keuze van uitvaartondernemer en invulling van de uitvaart."], ["De uitkering groeit automatisch mee met de stijgende kosten van uitvaarten.", "Een vast kapitaal groeit niet vanzelf mee; het risico van te lage dekking ligt juist bij de klant."], ["De uitvaartverzekeraar regelt altijd de volledige uitvaart, zonder dat nabestaanden iets hoeven te doen.", "Dat is het kenmerk van een naturaverzekering, waarbij diensten worden geleverd in plaats van geld."], ["De uitkering is nooit belast en valt altijd buiten de nalatenschap.", "De fiscale behandeling hangt af van de situatie; een algemene vrijstelling zoals hier beschreven bestaat niet."]]],
["Een klant met een naturauitvaartverzekering wil een uitvaart met extra wensen die niet in het verzekerde pakket zitten. Wat geldt?", [["Het verzekerde pakket wordt geleverd; extra wensen betalen de nabestaanden zelf.", "Een naturaverzekering dekt de overeengekomen diensten en goederen. Wat daarbuiten valt, moeten nabestaanden zelf betalen, tenzij de polis anders bepaalt."], ["De verzekeraar moet alle wensen van de overledene uitvoeren, ongeacht de kosten.", "Een naturapolis dekt een omschreven pakket; onbeperkte uitvoering van alle wensen is niet verzekerd."], ["De nabestaanden krijgen de waarde van het pakket in geld uitgekeerd en regelen alles zelf.", "Bij natura worden juist diensten geleverd; uitkering in geld is kenmerkend voor een kapitaalverzekering."], ["Extra wensen zijn niet toegestaan bij een naturaverzekering.", "Extra wensen zijn mogelijk, maar komen voor eigen rekening; ze zijn niet verboden."]]],
["Een klant van 70 wil zijn kapitaaluitvaartverzekering met levenslange premiebetaling niet langer voortzetten, maar de dekking ook niet helemaal kwijtraken. Welke mogelijkheid ligt voor de hand?", [["Premievrij maken: de premiebetaling stopt en het verzekerde bedrag daalt.", "Bij premievrij maken blijft een lager kapitaal verzekerd op basis van de al betaalde premies. Zo houdt de klant een deel van de dekking zonder verdere premie."], ["De verzekering opzeggen en de betaalde premies volledig terugvragen.", "Opzeggen leidt niet tot teruggave van alle premies; het risico is in de afgelopen jaren al gedekt geweest."], ["De premiebetaling stoppen met behoud van het volledige verzekerde bedrag.", "Zonder verdere premie kan het volledige kapitaal niet in stand blijven; de dekking wordt dan verlaagd."], ["De verzekering omzetten in een naturaverzekering, waarvoor geen premie meer verschuldigd is.", "Ook een naturaverzekering kost premie; omzetting is niet een manier om premievrij verzekerd te zijn."]]],
["Bij welk type schade stellen inboedel- en reispolissen meestal als voorwaarde dat de verzekerde aangifte doet bij de politie?", [["Bij diefstal, inbraak, beroving en vandalisme.", "Bij strafbare feiten vragen verzekeraars een aangifte als bevestiging van de gebeurtenis en ter bestrijding van fraude."], ["Bij elke waterschade door een gesprongen leiding.", "Een gesprongen leiding is geen strafbaar feit; daar is een melding bij de verzekeraar voldoende."], ["Bij storm- en hagelschade aan het dak van de woning.", "Natuurgebeurtenissen zijn geen strafbare feiten; aangifte bij de politie is daar niet aan de orde."], ["Bij schade die de verzekerde zelf per ongeluk aan zijn eigen spullen heeft toegebracht.", "Bij eigen onoplettendheid is er geen dader en geen strafbaar feit, dus ook geen aangifte."]]],
["Wat betekent het als een schade-expert is geregistreerd bij het NIVRE?", [["Dat hij lid is van de beroepsorganisatie van experts, met kwaliteitseisen en tuchtrecht.", "Registratie staat voor kwaliteit en onafhankelijkheid volgens de regels van de beroepsorganisatie. Verzekerden kunnen bij een klacht over het handelen van een register-expert ook het tuchtrecht inschakelen."], ["Dat hij namens de verzekeraar bindend mag beslissen of een schade onder de polis is gedekt.", "Een expert stelt oorzaak en omvang van de schade vast; de dekkingsvraag beslist de verzekeraar."], ["Dat hij een vergunning van de AFM heeft om verzekeringen te adviseren.", "Een AFM-vergunning ziet op financiële dienstverlening; NIVRE-registratie gaat over de beroepsgroep van experts."], ["Dat hij uitsluitend schaden onder een bepaald bedrag mag behandelen.", "Registratie zegt niets over een maximaal schadebedrag; experts behandelen schaden van elke omvang."]]],
["De expert van de verzekeraar heeft de omvang van een brandschade vastgesteld. Betekent dit dat de verzekeraar de schade ook moet vergoeden?", [["Nee, de expert stelt oorzaak en omvang vast; de dekking beoordeelt de verzekeraar apart.", "Expertise en dekking zijn verschillende vragen. Vaak wordt de expertise uitgevoerd onder voorbehoud van dekking."], ["Ja, zodra een expert de schade heeft vastgesteld, heeft de verzekeraar de dekking erkend.", "Het inschakelen van een expert is geen erkenning van dekking; de verzekeraar kan nog steeds een uitsluiting inroepen."], ["Ja, tenzij de verzekerde zelf een contra-expert inschakelt.", "Het inschakelen van een contra-expert gaat over de omvang van de schade, niet over het bestaan van dekking."], ["Nee, de verzekerde moet het rapport eerst laten goedkeuren door Kifid.", "Kifid keurt geen expertiserapporten goed; het behandelt pas klachten na een geschil met de verzekeraar."]]],
["Een verzekeraar ontdekt dat een verzekerde bij een claim bewust nota's heeft vervalst om een hogere uitkering te krijgen. Welke maatregelen zijn gebruikelijk?", [["Uitkering weigeren, de polis beëindigen, kosten verhalen en de fraudeur registreren.", "Bij fraude vervalt het recht op uitkering. Verzekeraars kunnen de relatie beëindigen, onderzoekskosten verhalen, aangifte doen en de fraudeur registreren volgens het branchebrede protocol."], ["Alleen het gefraudeerde deel van de claim niet vergoeden en de rest volledig uitbetalen.", "Bij fraude vervalt doorgaans het recht op de hele uitkering voor die gebeurtenis, niet alleen het overdreven deel."], ["De premie voor het komende jaar verhogen, maar de claim gewoon uitbetalen.", "Een premieverhoging is geen gangbare reactie op fraude en laat de uitkering niet in stand."], ["Niets doen, omdat alleen de politie maatregelen mag nemen bij valsheid in geschrift.", "Een verzekeraar mag civielrechtelijk en volgens het brancheprotocol optreden, naast een eventuele strafzaak."]]],
["Wat is het doel van de Gedragscode Behandeling Letselschade?", [["Een zorgvuldige en voortvarende afwikkeling, met het slachtoffer centraal.", "Deze code van zelfregulering geeft normen voor de omgang tussen slachtoffer, belangenbehartiger en verzekeraar, zoals tijdige communicatie en een respectvolle behandeling."], ["Het vastleggen van vaste bedragen voor smartengeld per soort letsel.", "De code gaat over het proces van afwikkeling; smartengeld wordt per geval bepaald, met rechtspraak als richtpunt."], ["Het verplichten van slachtoffers om alleen met een advocaat van de verzekeraar te werken.", "De code erkent juist het recht van het slachtoffer op een eigen belangenbehartiger."], ["Het regelen welke verzekeraar bij samenloop de letselschade moet betalen.", "Samenloop wordt in de wet en in afspraken tussen verzekeraars geregeld; de code gaat over de bejegening en afwikkeling."]]],
["Na een waterschade wil mevrouw Van Dijk de doorweekte vloerbedekking direct weggooien, voordat de expert is langs geweest. Wat is een verstandig advies?", [["Eerst foto's maken en de zaken zo mogelijk bewaren, of eerst overleggen met de verzekeraar.", "Zo kan de schade nog worden vastgesteld, terwijl verdere schade wordt beperkt. Zonder bewijs kan de beoordeling van oorzaak en omvang lastig worden."], ["Alles direct weggooien en later een schatting van de waarde doorgeven, want de verzekeraar vergoedt de opgegeven waarde.", "Een verzekeraar vergoedt de aantoonbare schade; zonder bewijs kan de beoordeling van oorzaak en omvang worden bemoeilijkt."], ["Niets aanraken en de natte vloerbedekking laten liggen tot de expert komt, ook als er verdere schade ontstaat.", "De bereddingsplicht vraagt juist dat verdere schade wordt beperkt; bewijs kan met foto's worden vastgelegd."], ["De vloerbedekking laten vervangen en de nota pas indienen als de verzekeraar dekking heeft bevestigd.", "Dit kan, maar zonder bewijs van de oude situatie kan de verzekeraar de schade moeilijk vaststellen; vastleggen gaat voor."]]],
["Binnen welke termijn moet een consument zijn klacht bij Kifid indienen nadat de verzekeraar een definitief standpunt over de klacht heeft ingenomen?", [["Binnen drie maanden.", "Het reglement van de Geschillencommissie van Kifid noemt een termijn van drie maanden na het definitieve standpunt van de financiële dienstverlener."], ["Binnen twee weken.", "Twee weken is veel korter dan de termijn in het reglement; de consument heeft drie maanden."], ["Binnen vijf jaar, gelijk aan de verjaringstermijn van een vordering uit onrechtmatige daad.", "De verjaringstermijn uit het BW is iets anders dan de indieningstermijn bij Kifid."], ["Er geldt geen termijn, zolang de vordering nog niet is verjaard.", "Het reglement kent wel degelijk een indieningstermijn na het definitieve standpunt."]]],
["Wat betaalt een consument om een klacht over zijn verzekeraar bij Kifid in te dienen?", [["Niets; de klachtbehandeling is voor consumenten kosteloos.", "Kifid wordt gefinancierd door de aangesloten financiële dienstverleners; consumenten betalen voor het indienen van een klacht geen bijdrage."], ["Een vast bedrag dat afhangt van de hoogte van de vordering.", "Een bijdrage die meegroeit met de vordering geldt niet voor consumenten bij Kifid."], ["Het griffierecht dat ook bij de kantonrechter geldt.", "Kifid is een geschilleninstantie buiten de rechter; griffierecht is daar niet van toepassing."], ["De kosten van de verzekeraar, als de consument de zaak verliest.", "Een consument hoeft bij Kifid geen kosten van de verzekeraar te vergoeden als zijn klacht wordt afgewezen."]]],
["In de polisvoorwaarden van een inboedelverzekering staat een bepaling die op twee manieren redelijk kan worden gelezen. Hoe wordt die bepaling bij een consument uitgelegd?", [["In de zin die voor de consument het gunstigst is.", "Bij twijfel over de betekenis van een beding in een overeenkomst met een consument geldt de voor hem gunstigste uitleg. Dat stimuleert verzekeraars om duidelijke voorwaarden te schrijven."], ["In de zin die de verzekeraar bij het opstellen bedoelde, omdat hij de voorwaarden heeft geschreven.", "Het is juist de opsteller die het risico van onduidelijkheid draagt, niet de consument."], ["In de zin die de adviseur van de klant tijdens het adviesgesprek heeft uitgelegd.", "Wat een adviseur zegt, kan relevant zijn voor zijn eigen zorgplicht, maar bepaalt niet de uitleg van de polis."], ["De bepaling is nietig, waardoor het onderwerp helemaal niet meer is gedekt.", "Onduidelijkheid leidt tot uitleg in het voordeel van de consument, niet tot nietigheid en verlies van dekking."]]],
["Een consument dient een klacht over zijn verzekeraar in bij de AFM. Wat doet de AFM hiermee?", [["De AFM behandelt geen individuele klachten, maar kan de melding gebruiken in haar toezicht.", "De AFM houdt toezicht op het gedrag van financiële ondernemingen in het algemeen. Voor een oplossing van zijn eigen geschil moet de consument bij de verzekeraar en daarna bij Kifid zijn."], ["De AFM doet een bindende uitspraak over de klacht, waartegen geen beroep mogelijk is.", "Bindende uitspraken over individuele geschillen doet Kifid of de rechter, niet de AFM."], ["De AFM verwijst de klacht door naar De Nederlandsche Bank, die individuele klachten behandelt.", "DNB houdt prudentieel toezicht en behandelt evenmin individuele klachten van consumenten."], ["De AFM legt de verzekeraar een schadevergoeding aan de consument op.", "De AFM kan boetes en maatregelen opleggen, maar kent geen schadevergoeding toe aan een individuele consument."]]],
["Moet een consument met een geschil over een schade-uitkering eerst naar Kifid voordat hij naar de rechter mag?", [["Nee, Kifid is een alternatief; de consument kan ook rechtstreeks naar de rechter.", "Kifid biedt een laagdrempelige en kosteloze route, maar de toegang tot de rechter blijft open. Wel kan een eenmaal gekozen bindende procedure de route naar de rechter beperken."], ["Ja, een procedure bij de rechter is pas mogelijk na een uitspraak van Kifid.", "Er is geen wettelijke plicht om eerst naar Kifid te gaan; de rechter is rechtstreeks toegankelijk."], ["Ja, maar alleen als het geschil over een bedrag gaat dat lager is dan de verzekerde som.", "De hoogte van het bedrag maakt Kifid niet tot een verplichte eerste stap."], ["Nee, maar een consument kan na een procedure bij de rechter nog naar Kifid voor een tweede oordeel.", "Kifid behandelt in de regel geen zaken waarover de rechter al heeft beslist; het is geen beroepsinstantie boven de rechter."]]],
["Wat is het Extern Verwijzingsregister dat financiële instellingen via Stichting CIS gebruiken?", [["Een register van personen met een incident, zoals fraude, als waarschuwing voor instellingen.", "Instellingen kunnen elkaar zo waarschuwen voor personen die een risico vormen. Registratie gebeurt volgens een vast protocol, met eisen aan zorgvuldigheid en duur."], ["Een register van alle consumenten die ooit een schade hebben gemeld bij een verzekeraar.", "Een gewone schademelding leidt niet tot opname in dit register; het gaat om incidenten zoals fraude."], ["Een openbaar register waarin iedereen kan nagaan of een persoon een geldige verzekering heeft.", "Het register is niet openbaar; alleen aangesloten instellingen kunnen het raadplegen."], ["Een register van adviseurs die hun AFM-vergunning zijn kwijtgeraakt.", "Het AFM-register bevat informatie over vergunningen; het Extern Verwijzingsregister gaat over klanten met een incident."]]],
["Een consument vindt dat hij onterecht in een CIS-registratie staat. Tot wie moet hij zich in de eerste plaats wenden om de registratie te laten corrigeren?", [["Tot de verzekeraar die de registratie heeft gedaan.", "De instelling die de gegevens heeft aangeleverd, is verantwoordelijk voor de juistheid ervan. Daar kan de consument om correctie of verwijdering vragen."], ["Tot de AFM, die de registraties van verzekeraars namens consumenten aanpast.", "De AFM past geen individuele registraties aan; de verantwoordelijke instelling moet dat doen."], ["Tot de rechtbank, omdat een registratie alleen door een rechter kan worden doorgehaald.", "Een rechter kan uiteindelijk oordelen, maar de eerste stap is een verzoek aan de instelling zelf."], ["Tot zijn eigen adviseur, die bevoegd is registraties bij CIS te wijzigen.", "Een adviseur heeft geen bevoegdheid om CIS-registraties te wijzigen; dat doet de registrerende instelling."]]],
["Waarom registreren verzekeraars schadeclaims in een centrale databank van CIS?", [["Om patronen zoals dubbele claims of fraude te kunnen herkennen.", "Een centrale registratie maakt zichtbaar of iemand dezelfde schade bij meer verzekeraars meldt of een opvallend schadeverleden heeft. Dat helpt risico's goed in te schatten en fraude te bestrijden."], ["Om de premie van alle klanten in Nederland centraal te kunnen vaststellen.", "Elke verzekeraar stelt zijn eigen premie vast; CIS bepaalt geen premies."], ["Om consumenten de mogelijkheid te geven hun schadeverleden openbaar te maken.", "De databank is niet openbaar; consumenten kunnen wel hun eigen gegevens inzien."], ["Om aan de Belastingdienst door te geven welke schade-uitkeringen zijn gedaan.", "CIS is geen informatiepunt voor de Belastingdienst; het doel is risicobeoordeling en fraudebestrijding."]]],
["In welk document is in Nederlandse polissen vastgelegd wat onder terrorisme wordt verstaan en hoe de dekking werkt?", [["In het Clausuleblad terrorismedekking bij de NHT.", "Verzekeraars nemen dit clausuleblad op in hun polissen. Het bevat de definities en verwijst naar het protocol van de NHT voor de afwikkeling."], ["In de Wet op het financieel toezicht, die een vaste wettelijke definitie van terrorisme bevat.", "De Wft regelt toezicht en gedrag van financiële ondernemingen; de definitie van terrorisme in polissen staat in het clausuleblad."], ["In de algemene voorwaarden van iedere verzekeraar afzonderlijk, met per verzekeraar een eigen omschrijving.", "Juist om uniformiteit te bereiken gebruiken verzekeraars een gezamenlijk clausuleblad met dezelfde definities."], ["In de molestclausule, die terrorisme als vorm van molest volledig uitsluit.", "Terrorisme is apart geregeld en via de NHT juist binnen grenzen gedekt, los van de molestuitsluiting."]]],
["Na een grote terroristische aanslag is de totale schade hoger dan het bedrag dat de NHT per jaar kan uitkeren. Wat is het gevolg voor verzekerden?", [["Zij krijgen een door de NHT vastgesteld percentage, uitbetaald via hun eigen verzekeraar.", "Door het jaarlijkse maximum wordt de beschikbare capaciteit naar evenredigheid verdeeld. De verzekerde ontvangt de uitkering van zijn eigen verzekeraar."], ["Zij krijgen geen enkele vergoeding, omdat terrorisme bij overschrijding van het maximum volledig is uitgesloten.", "Bij overschrijding wordt de beschikbare capaciteit verdeeld; verzekerden krijgen dan een deel van hun schade vergoed."], ["Zij kunnen het tekort rechtstreeks bij de NHT claimen, die daarvoor een aanvullend fonds heeft.", "De NHT heeft geen rechtstreekse relatie met verzekerden en heeft een maximum aan capaciteit."], ["Alleen de eerste verzekerden die hun schade melden, krijgen volledig vergoed tot het maximum is bereikt.", "De verdeling gebeurt naar evenredigheid voor alle verzekerden, niet op volgorde van melding."]]],
["Welke gebeurtenissen vallen naast terrorisme onder de regeling van het Clausuleblad terrorismedekking?", [["Kwaadwillige besmetting en preventieve overheidsmaatregelen.", "Het clausuleblad omvat ook opzettelijke besmetting met bijvoorbeeld ziektekiemen en maatregelen die de overheid neemt om terrorisme te voorkomen of de gevolgen te beperken."], ["Binnenlandse onlusten en oproer, die volledig onder de NHT-regeling vallen.", "Binnenlandse onlusten en oproer zijn vormen van molest die buiten de terrorismeregeling vallen."], ["Overstroming door het bezwijken van een primaire waterkering.", "Dat is een overstromingsrisico waarvoor andere regels gelden; het valt niet onder het clausuleblad."], ["Alle vormen van vandalisme door onbekende daders.", "Gewone vandalisme is een regulier verzekerd of uitgesloten risico en valt niet onder de terrorismeregeling."]]],
["Wat wordt verstaan onder een primaire waterkering?", [["Een wettelijk aangewezen kering die beschermt tegen water van zee, grote rivieren of meren.", "Primaire waterkeringen beschermen tegen buitenwater en zijn in de wet vastgelegd. Schade door het bezwijken ervan is in particuliere polissen doorgaans uitgesloten."], ["Iedere kade langs een sloot of kanaal in een polder, die door het waterschap wordt beheerd en onderhouden.", "Kades langs kanalen en sloten zijn regionale of niet-primaire waterkeringen, geen primaire keringen."], ["De dakgoot en afvoer van een woning die regenwater moeten afvoeren.", "Een dakgoot is geen waterkering; het begrip ziet op landelijke bescherming tegen overstroming."], ["Een tijdelijke zandzakkenwal die bij hoog water door de brandweer wordt opgeworpen.", "Een noodmaatregel is geen wettelijk aangewezen waterkering."]]],
["Wanneer kan een gedupeerde aanspraak maken op een tegemoetkoming op grond van de Wet tegemoetkoming schade bij rampen?", [["Pas als de overheid de regeling voor die specifieke ramp heeft opengesteld.", "De Wts werkt niet automatisch: per ramp wordt besloten of en voor welk gebied de regeling opengaat. Daarna gelden de voorwaarden van die regeling."], ["Altijd, zodra de schade groter is dan het eigen risico van de woonhuisverzekering.", "De Wts is geen aanvulling op elke verzekerde schade; zij geldt alleen als de overheid haar voor een ramp openstelt."], ["Alleen als de verzekeraar de schade schriftelijk heeft afgewezen wegens een uitsluiting.", "Een afwijzing door de verzekeraar is geen voorwaarde; het besluit van de overheid om de regeling open te stellen is bepalend."], ["Uitsluitend als de gedupeerde lid is van een waterschap in het getroffen gebied.", "Lidmaatschap van een waterschap is geen voorwaarde voor een tegemoetkoming."]]],
["Wat is in woonhuis- en inboedelpolissen doorgaans het verschil tussen schade door neerslag en schade door overstroming?", [["Neerslag is regen, sneeuw of hagel die binnendringt; overstroming is water dat buiten de oevers of keringen treedt.", "Neerslagschade is vaak gedekt. Bij overstroming hangt de dekking af van de oorzaak en het type waterkering, en is bezwijken van een primaire kering doorgaans uitgesloten."], ["Er is geen verschil; beide begrippen betekenen in de polis dat water van buitenaf de woning binnenkomt en schade veroorzaakt.", "Polissen maken juist een duidelijk onderscheid, omdat de dekking voor beide sterk verschilt."], ["Neerslag is water uit een kapotte waterleiding; overstroming is water uit de riolering.", "Water uit een leiding is leidingwater, geen neerslag; de begrippen worden hier door elkaar gehaald."], ["Neerslag is alleen gedekt bij allriskpolissen; overstroming alleen bij polissen op basis van genoemde gevaren.", "Het onderscheid gaat over de oorzaak van het water, niet over het type dekking."]]],
["Waarom is grootschalige overstroming door het bezwijken van een primaire waterkering moeilijk verzekerbaar voor verzekeraars?", [["Omdat één gebeurtenis gelijktijdig zeer veel verzekerden kan treffen (cumulatierisico).", "Bij een dijkdoorbraak kunnen duizenden woningen tegelijk schade lijden. Verzekeraars kunnen zo'n concentratie van risico moeilijk spreiden."], ["Omdat de kans op overstroming zo groot is dat elke woning in Nederland jaarlijks schade heeft.", "De kans op een dijkdoorbraak is juist klein; het probleem is de omvang bij een gebeurtenis, niet de frequentie."], ["Omdat overstromingsschade altijd geleidelijk ontstaat en daardoor niet onvoorzien is.", "Een dijkdoorbraak is een plotselinge gebeurtenis; het probleem ligt in de concentratie van schade."], ["Omdat de Wft verzekeraars verbiedt om overstromingsschade te dekken.", "De Wft bevat zo'n verbod niet; het gaat om de verzekerbaarheid van het risico."]]],
["Welke informatie hoort een adviseur in ieder geval te verzamelen bij een advies over een particulier verzekeringspakket?", [["Gezinssituatie, bezittingen, bestaande verzekeringen en de omgang van de klant met risico.", "Pas met dit beeld kan de adviseur bepalen welke risico's de klant loopt, wat al gedekt is en welke risico's de klant zelf kan en wil dragen."], ["Alleen de premie die de klant maximaal per maand wil betalen.", "Het budget is relevant, maar zonder kennis van risico's en bestaande dekkingen kan geen passend advies worden gegeven."], ["Alleen de verzekeringen die de klant zelf wil afsluiten, omdat het initiatief bij de klant ligt.", "De adviseur moet ook risico's signaleren die de klant zelf niet noemt; dat hoort bij zijn zorgplicht."], ["Het volledige pensioenoverzicht en de belastingaangifte van de laatste vijf jaar.", "Voor een schadeadvies zijn deze stukken meestal niet nodig; de inventarisatie moet passen bij het advies."]]],
["Waarom is het voor een adviseur belangrijk het advies en de afwegingen in een klantdossier vast te leggen?", [["Zo kan hij aantonen dat hij zorgvuldig heeft geadviseerd en is het advies te volgen.", "Bij een klacht of geschil ligt de bewijslast voor zorgvuldige dienstverlening in de praktijk vaak bij de adviseur. Een goed dossier laat zien wat is besproken en waarom."], ["Omdat de verzekeraar zonder klantdossier geen polis mag afgeven.", "De verzekeraar accepteert op basis van de aanvraag; het adviesdossier is een verantwoordelijkheid van de adviseur."], ["Omdat het dossier de polisvoorwaarden vervangt als die onduidelijk zijn.", "Het dossier kan helpen bij uitleg over het advies, maar vervangt nooit de polisvoorwaarden."], ["Omdat de klant het dossier moet ondertekenen voordat de premie kan worden geïncasseerd.", "Premie-incasso hangt niet af van een ondertekend adviesdossier."]]],
["Een bemiddelaar zegt tegen klanten dat hij adviseert op basis van een onpartijdige analyse. Wat vraagt de IDD dan van hem?", [["Dat hij een voldoende groot aantal producten op de markt vergelijkt.", "Wie zich op een onpartijdige analyse beroept, mag zich niet beperken tot een paar aanbieders. Het advies moet steunen op een vergelijking van een representatief deel van de markt."], ["Dat hij alleen producten adviseert van verzekeraars waarmee hij geen afspraken heeft.", "Afspraken met verzekeraars zijn niet verboden; het gaat erom dat hij voldoende producten vergelijkt."], ["Dat hij geen enkele vorm van beloning ontvangt voor zijn bemiddeling.", "Onpartijdigheid gaat over de breedte van de vergelijking, niet over het ontbreken van beloning."], ["Dat hij uitsluitend het product met de laagste premie mag adviseren.", "Het passende product is niet altijd het goedkoopste; dekking en voorwaarden wegen ook mee."]]],
["Wat bepaalt de IDD over de beloning van een verzekeringsdistributeur?", [["Zijn beloning mag niet strijdig zijn met zijn plicht in het klantbelang te handelen.", "Beloningen mogen geen prikkel geven om een product te adviseren dat niet het beste bij de klant past. Dat geldt ook voor verkoopdoelen en bonussen."], ["Hij mag uitsluitend door de klant worden beloond, nooit door de verzekeraar.", "Bij veel schadeverzekeringen is provisie van de verzekeraar toegestaan; een volledig verbod geldt alleen voor specifieke producten."], ["Zijn beloning moet een vast percentage van de premie zijn dat voor alle verzekeraars gelijk is.", "De IDD schrijft geen vast percentage voor; zij regelt wel dat de beloning het klantbelang niet mag schaden."], ["Er gelden geen regels voor beloning bij schadeverzekeringen, alleen bij levensverzekeringen.", "De regel dat beloning niet in strijd mag zijn met het klantbelang geldt voor alle verzekeringsdistributie."]]],
["Een reisbureau biedt bij het boeken van een vakantie een annuleringsverzekering aan. Hoe kwalificeert de IDD het reisbureau hier?", [["Als nevenverzekeringsdistributeur, omdat verzekeren een aanvulling is op de reis.", "De IDD kent een lichter regime voor partijen die verzekeringen als aanvulling op een product of dienst aanbieden. Kernplichten, zoals een verkoop die past bij de behoeften van de klant, gelden wel."], ["Als verzekeraar, omdat het reisbureau het risico van annulering zelf draagt.", "Het reisbureau draagt het risico niet; dat doet de verzekeraar voor wie het reisbureau bemiddelt."], ["Als volmachtbedrijf, omdat het reisbureau zelf polissen mag afgeven.", "Een volmachtbedrijf heeft een volmacht van de verzekeraar om risico's te accepteren; een reisbureau dat aanbiedt is daarom nog geen gevolmachtigd agent."], ["Het valt helemaal buiten de IDD, omdat reisverzekeringen geen financiële producten zijn.", "Reis- en annuleringsverzekeringen zijn wel verzekeringsproducten; de IDD is ook op deze distributie van toepassing."]]],
["Mevrouw Jansen meldt haar adviseur dat ze een grote uitbouw laat bouwen. De adviseur doet niets met de melding. Na een brand blijkt de woning onderverzekerd. Hoe wordt dit beoordeeld?", [["De adviseur heeft waarschijnlijk zijn zorgplicht geschonden en kan aansprakelijk zijn voor het nadeel van de klant.", "Een klant die een relevante wijziging bij zijn adviseur meldt, mag erop rekenen dat die actie onderneemt, zoals het aanpassen van het verzekerde bedrag. Nalaten daarvan kan een beroepsfout zijn."], ["De adviseur is niet aansprakelijk, omdat alleen de klant verantwoordelijk is voor het melden aan de verzekeraar.", "Als de klant de wijziging aan haar adviseur meldt, rust op die adviseur een eigen zorgplicht om ermee aan de slag te gaan."], ["De verzekeraar moet volledig uitkeren, omdat een melding aan de adviseur altijd als melding aan de verzekeraar geldt.", "Of kennis van de adviseur aan de verzekeraar wordt toegerekend, hangt van de relatie af; de vraag gaat hier over de zorgplicht van de adviseur."], ["Er is geen probleem, omdat een uitbouw altijd automatisch onder de bestaande woonhuisverzekering valt.", "Een uitbouw verhoogt de herbouwwaarde; zonder aanpassing van het verzekerde bedrag dreigt juist onderverzekering."]]],
["Een klant zonder AVP wil op advies van zijn adviseur toch geen AVP afsluiten om premie te besparen. Wat moet de adviseur doen?", [["De klant wijzen op het risico van onbeperkte aansprakelijkheid en het besluit vastleggen.", "De klant beslist, maar de adviseur moet zorgen dat hij het risico begrijpt. Vastleggen laat later zien dat de klant bewust heeft gekozen."], ["De klant weigeren als cliënt, omdat een advies zonder AVP nooit passend kan zijn.", "Een klant mag een risico zelf dragen; de adviseur hoeft de relatie niet te beëindigen."], ["Een AVP toch afsluiten, omdat de adviseur bij een zorgplicht de keuze voor de klant mag maken.", "Zonder instemming van de klant mag de adviseur geen verzekering sluiten; de zorgplicht gaat niet zo ver."], ["Niets, omdat de klant zelf verantwoordelijk is en de adviseur geen informatieplicht heeft.", "De adviseur moet de klant wel informeren over de gevolgen van zijn keuze; anders kan hij zijn zorgplicht schenden."]]],
["Welke vakbekwaamheid is nodig voor een adviseur die particulieren adviseert over schadeverzekeringen?", [["Wft Basis en Wft Schadeverzekering Particulier, en daarna permanente educatie.", "De Wft-diplomastructuur combineert een basismodule met een productmodule. Na het behalen moet de adviseur zijn kennis periodiek actueel houden."], ["Alleen het Wft-diploma Schadeverzekering Zakelijk, omdat dit ook de particuliere producten omvat.", "Particuliere en zakelijke schadeverzekeringen hebben elk een eigen module; de zakelijke module vervangt de particuliere niet."], ["Geen diploma, omdat schadeverzekeringen geen complexe producten zijn.", "Ook voor advies over schadeverzekeringen gelden wettelijke eisen aan vakbekwaamheid."], ["Alleen een diploma rechten, omdat het advies vooral over polisvoorwaarden gaat.", "Een juridische opleiding is geen vervanging van de verplichte Wft-diploma's."]]],
["Wat is een gevolmachtigd agent (volmachtbedrijf) in de schadeverzekeringsmarkt?", [["Een bemiddelaar die namens de verzekeraar risico's mag accepteren, polissen mag afgeven en vaak schaden mag afhandelen.", "De verzekeraar draagt het risico, maar laat acceptatie en administratie over aan het volmachtbedrijf binnen afgesproken grenzen."], ["Een tussenpersoon die uitsluitend namens de klant onderhandelt met verzekeraars, zonder bevoegdheden van de verzekeraar.", "Dat beschrijft een gewone adviseur; een volmachtbedrijf heeft juist bevoegdheden namens de verzekeraar."], ["Een instantie die door de AFM is aangewezen om klachten over verzekeraars te behandelen.", "Klachten worden behandeld door Kifid; een volmachtbedrijf is een marktpartij."], ["Een herverzekeraar die het risico van een verzekeraar voor een deel overneemt.", "Een herverzekeraar neemt risico over; een gevolmachtigd agent draagt zelf geen verzekeringsrisico."]]],
["Wie stelt volgens de IDD het informatiedocument (IPID) voor een schadeverzekering op?", [["De ontwikkelaar van het product, meestal de verzekeraar.", "Het informatiedocument beschrijft het product in een vast format. De partij die het product ontwerpt, is daarvoor verantwoordelijk; de distributeur verstrekt het aan de klant."], ["De adviseur, op basis van de persoonlijke situatie van de klant.", "Het IPID is gestandaardiseerd en productgebonden, niet afgestemd op de individuele klant."], ["De AFM, die voor elk product op de markt een informatiedocument publiceert.", "De AFM houdt toezicht, maar stelt de documenten van aanbieders niet zelf op."], ["Het Kifid, zodat consumenten producten onafhankelijk kunnen vergelijken.", "Kifid behandelt klachten en geeft geen productinformatie uit."]]],
["Wat moet een verzekeringsdistributeur onder de regels voor productontwikkeling en -toezicht regelen voor de producten die hij verkoopt?", [["Dat hij de productinformatie en de doelgroep kent en het product binnen die doelgroep aanbiedt.", "De verzekeraar bepaalt de doelgroep, maar de distributeur moet die informatie hebben en gebruiken. Zo wordt voorkomen dat producten buiten de doelgroep worden verkocht."], ["Dat hij zelf een volledig eigen productontwikkelingsproces doorloopt voor elk product van de verzekeraar.", "Het ontwikkelen van het product is een taak van de verzekeraar; de distributeur heeft een eigen, aanvullende rol."], ["Dat hij elke productwijziging vooraf laat goedkeuren door de AFM.", "De AFM keurt producten niet vooraf goed; partijen moeten zelf zorgen voor een goed proces."], ["Niets, omdat deze regels alleen gelden voor de verzekeraar en niet voor de distributeur.", "Ook distributeurs hebben verplichtingen binnen dit stelsel, zoals het kennen van de doelgroep."]]]
];
